INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1516, 'plPL', 'Zew ziemi', 'Czas nadszedł, $gmłody szamanie:młoda szamanko;. $GStałeś:Stałaś; się $gsilny:silna;, a twój duch jest trwały jak ziemia. To, że $gwybrałeś:wybrałaś; ścieżkę szamana, świadczy o twojej mądrości, zanim jeszcze się $gwykazałeś:wykazałaś;.$B$BŻywioł ziemi pokieruje twoim przeznaczeniem i stanie się częścią ciebie, jeśli jesteś $ggotów:gotowa;. Musisz jednak stanąć przed samą ziemią. Jeśli jesteś $ggotów:gotowa;, ujrzysz rzeczy, o których wiedzą tylko szamani.$B$BOdszukaj spaczonych tropicieli na północy i zdobądź od nich dwa kopyta. Potem wróć do mnie, a porozmawiamy więcej o twojej przyszłości.$B', 'Przynieś 2 kopyta spaczonego tropiciela Canadze Przywoływaczowi Ziemi w Dolinie Prób.', '', 'Wróć do Canagi Przywoływacza Ziemi w Dolinie Prób w Durotarze.', '', '', '', '', 0),
(1517, 'plPL', 'Zew ziemi', 'Sapta to napój, który wiąże nasze duchy z żywiołami. Przesycony magią wywar pozwala tym o silnej woli widzieć żywioły tak, jak nie widzi ich nikt inny. Twój duch połączy się z żywiołem, dla którego stworzono saptę, a przepis zna tylko garstka wybranych szamanów.$B$BSaptę pije się zawsze w świętym miejscu i nigdzie indziej – zapamiętaj to.$B$BOdszukaj Skałę Duchów na południowy zachód stąd – znajdziesz ją na końcu Ukrytej Ścieżki. Wypij tam swoją saptę, a wtedy... cóż, $gsam:sama; zobaczysz.', 'Odszukaj Skałę Duchów i wypij saptę ziemi.', '', '', '', '', '', '', 0),
(1518, 'plPL', 'Zew ziemi', 'Weź ode mnie ten surowy kwarc i zanieś go Canadze Przywoływaczowi Ziemi na dowód naszego spotkania. Wykona dla ciebie totem, a ten kamyk stanie się jego sercem. Choć wydaje się mały, przekonasz się, że rozmiar nie ma znaczenia i że nawet najmniejsze rzeczy potrafią przetrwać wiele innych.$B$BBądź $gcierpliwy:cierpliwa;, $N. Pozostań $gsilny:silna;. I szukaj mądrości. Tego ziemia od ciebie oczekuje. W końcu staniesz się jednym z ziemią – szanuj ją, a ona będzie szanować ciebie.', 'Przynieś surowy kwarc Canadze Przywoływaczowi Ziemi w Dolinie Prób.', '', '', '', '', '', '', 0),
(1519, 'plPL', 'Zew ziemi', 'Nadszedł czas, $N. Twoje ciało dojrzewa i nabiera sił, a twój duch jest trwały jak ziemia. Widzę to w tobie – już masz w sobie mądrość.$B$BZiemia prowadzi nasz lud i przemawia do nas, a z czasem przemówi i do ciebie. Musisz jednak przejść próbę. Jeśli jesteś $ggotów:gotowa;, ujrzysz rzeczy znane tylko naszemu rodowi.$B$BOdszukaj szamanki Sierściogrzbietów w ich wąwozie na wschodzie i zabierz im maść, której używają w swoich rytuałach. Wróć do mnie dopiero wtedy, gdy zbierzesz jej dość na własny wywar.', 'Przynieś 2 porcje rytualnej maści jasnowidzce Kruczemu Pióru w Obozie Naracze.', '', 'Wróć do jasnowidzki Kruczego Pióra na Płaskowyżu Czerwonej Chmury w Mulgorze.', '', '', '', '', 0),
(1520, 'plPL', 'Zew ziemi', 'Sapta to napój, który wiąże nasze duchy z żywiołami. Przesycony magią wywar pozwala tym o otwartych umysłach widzieć żywioły tak, jak nikt ich dotąd nie widział. Twój duch na zawsze zwiąże się z żywiołem, dla którego stworzono saptę, a tajemnice jej przyrządzania zna tylko garstka wybranych z naszego ludu.$B$BSaptę spożywa się zawsze w świętym miejscu i nigdzie indziej.$B$BOdszukaj szamańską kaplicę na wschód stąd i wypij tam saptę.', 'Odszukaj Skałę Kodo i wypij saptę ziemi.', '', '', '', '', '', '', 0),
(1521, 'plPL', 'Zew ziemi', 'Weź ode mnie ten surowy kwarc i zanieś go Jasnowidzce Krucze Pióro na dowód naszego spotkania. Wykona dla ciebie totem, a ten kamyk stanie się jego sercem. Choć wydaje się mały, przekonasz się, że rozmiar nie ma znaczenia i że nawet najmniejsze rzeczy potrafią przetrwać góry.$B$BBądź $gcierpliwy:cierpliwa;, $N. Pozostań $gsilny:silna;. I szukaj mądrości. Tego ziemia od ciebie oczekuje. W końcu staniesz się jednym z ziemią – szanuj ją, a ona będzie szanować ciebie.', 'Przynieś surowy kwarc Jasnowidzce Krucze Pióro w Obozie Naracze.', '', '', '', '', '', '', 0),
(8328, 'plPL', 'Szkolenie maga', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych magów na Wyspie Słońcobieżców szkoli Julia Słońcobij. Porozmawiaj z Julią i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BJulia – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Julią Słońcobij, nauczycielką magów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8329, 'plPL', 'Szkolenie wojownika', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych wojowników na Wyspie Słońcobieżców szkoli Jesthenis Słońcobij. Porozmawiaj z Jesthenisem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BJesthenis – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Jesthenisem Słońcobijem, nauczycielem wojowników, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8564, 'plPL', 'Szkolenie kapłana', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych kapłanów na Wyspie Słońcobieżców szkoli matrona Arena. Porozmawiaj z matroną i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BMatrona Arena – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z matroną Areną, nauczycielką kapłanów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9278, 'plPL', 'Witaj!', 'Witaj w świecie World of Warcraft!$B$BW podziękowaniu za zakup Edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Jaeleil w Lazurowej Strażnicy. Otrzymasz w zamian prezent: małego towarzysza, który będzie ci towarzyszył w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w świecie World of Warcraft!$B', 'Zanieś bon podarunkowy z Lazurowej Strażnicy Jaeleil w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9279, 'plPL', 'Żyjesz!', 'Nie zważaj na moje rany, $gbracie:siostro;. To cud, że ktokolwiek z nas przeżył!$b$bWyglądało na to, że się nie wybudzisz; od tygodni $gleżałeś:leżałaś; w stanie zawieszenia.$B$BCoś się wydarzyło i Exodar się rozbił. Wielu zginęło.$B$BAle ulżyło mi, że żyjesz, $N. Skoro będziesz przewodzić naszym staraniom, jestem pewien, że wkrótce dotrzemy w bezpieczne miejsce! Proenitus prosił, żebym przysłał cię do niego, gdy się ockniesz. Czeka na ciebie u stóp wzgórza. Idź po prostu ścieżką na południowy zachód.', 'Porozmawiaj z Proenitusem na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9280, 'plPL', 'Odnowienie kryształów leczniczych', 'Najpilniejszą sprawą jest wyczerpanie naszych kryształów leczniczych. Musimy je szybko odnowić!$B$BNiestety, w tej chwili jedynym sposobem jest pozyskanie krwi miejscowych ciem z doliny. Ich krew będzie odpowiednim zamiennikiem.$B$BĆmy można spotkać w wielu miejscach doliny, ale najwięcej jest ich na północnym zachodzie.', 'Zdobądź 8 fiolek krwi ćmy od pobliskich ciem z Doliny i oddaj je Proenitusowi na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Proenitusa na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(9283, 'plPL', 'Ratuj ocalałych!', 'Kryształy lecznicze zostały odnowione, ale to nie jedyny sposób, w jaki możemy pomóc rannym. Każdy draenei może czerpać z daru naaru, by leczyć. Musisz użyć tej zdolności, by uleczyć jednego z ocalałych z katastrofy.$b$bWiększość ocalałych znajdziesz na zachodzie i północnym zachodzie, ale katastrofa rozrzuciła nas po całej dolinie.$b$bOcaleni ucierpieli od promieniowania napromieniowanych kryształów energii, więc rozpoznasz ich po otaczającej ich czerwonej poświacie.$B$BMusisz ich ocalić, $N.', 'Użyj zdolności Dar naaru na jednym z ocalałych draenei rozproszonych po Dolinie Ammen, a następnie wróć do Zalduuna na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Zalduuna na Miejscu Katastrofy w Dolinie Ammen.', 'Uratowani ocaleli draenei', '', '', '', 0),
(9287, 'plPL', 'Szkolenie paladyna', '', '', '', '', '', '', '', '', 0),
(9288, 'plPL', 'Szkolenie łowcy', '', '', '', '', '', '', '', '', 0),
(9289, 'plPL', 'Szkolenie wojownika', '', '', '', '', '', '', '', '', 0),
(9290, 'plPL', 'Szkolenie maga', '', '', '', '', '', '', '', '', 0),
(9291, 'plPL', 'Szkolenie kapłana', '', '', '', '', '', '', '', '', 0),
(9293, 'plPL', 'Co musi zostać zrobione...', 'Pobliskie jezioro zostało skażone przez jeden z kryształów energii statku. Z tego powodu wiele roślin i zwierząt w Dolinie Ammen uległo mutacji.$B$BMam pewną teorię, jak uzdrowić jezioro, ale muszę zbadać próbki pobrane od zmutowanych smagaczy. Znajdziesz je na zachodzie, na Polach Ammen.$B$BPomożesz mi, $N?', 'Zbierz 10 próbek smagacza i zanieś je botaniczce Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do botaniczki Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(9294, 'plPL', 'Uzdrowienie jeziora', 'Dzięki niebiosom, chyba zadziała! Mam dla ciebie środek, który trzeba rozproszyć w Jeziorze Srebrnej Linii na południu. Zneutralizuje działanie napromieniowanego kryształu energii ze statku, który tam wpadł.$B$BPodpłyń do niego i rozprosz przy nim środek neutralizujący. Nie martw się, nie będziesz tam przebywać dość długo, by ulec napromieniowaniu.', 'Rozprosz środek neutralizujący przy napromieniowanym krysztale energii, a następnie wróć do botaniczki Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do botaniczki Taerix na Miejscu Katastrofy w Dolinie Ammen.', 'Rozprosz środek neutralizujący', '', '', '', 0),
(9303, 'plPL', 'Szczepienie', 'Zhanaa potrzebuje naszej pomocy przy odzyskiwaniu części z Exodaru. Taerix przygotowała szczepionkę, którą można podać lunozwierzom z Gniazdowego Lasu, żyjącym tam, gdzie leży sporo szczątków.$B$BPodejdź po prostu blisko do tych, które nie są dotknięte mutacją, i użyj na nich kryształu. Niestety pozostałe będziesz $gmusiał:musiała; zabić. Lunozwierze znajdziesz w Gąszczu Gniazdowego Lasu i na Wzgórzach Gniazdowego Lasu na południowym wschodzie.', 'Użyj kryształu szczepiącego na 6 lunozwierzach z Gniazdowego Lasu. Następnie wróć do Obrońcy Aldara na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Obrońcy Aldara na Miejscu Katastrofy w Dolinie Ammen.', 'Zaszczepione lunozwierze z Gniazdowego Lasu', '', '', '', 0),
(9305, 'plPL', 'Części zapasowe', 'Udało nam się odzyskać z wraku uszkodzony emiter holograficzny. Jeśli go naprawimy, będziemy mieli szansę odnaleźć innych ocalałych poza Doliną Ammen.$B$BW okolicy leżały urządzenia ze statku, które można było rozebrać na części zapasowe, ale miejscowe lunozwierze zabrały je, zanim zdążyliśmy do nich dotrzeć.$B$B$N, musisz udać się na południe do Gąszczu i na Wzgórza Gniazdowego Lasu i odnaleźć te części.', 'Zbierz 4 części zapasowe emitera, a następnie wróć do techniczki Zhanaa na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do techniczki Zhanaa na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(9306, 'plPL', '<DEPRECATED>Porozmawiaj z Obrońcą Aldarem', '$N, Obrońca Aldar szuka kogoś, kto zajmie się problemem ze zmutowanymi lunozwierzami w Gąszczu Gniazdowego Lasu. Musimy uporać się z niefortunnym skutkiem naszego niezamierzonego przybycia w to miejsce.$B$BZnajdziesz go na zewnątrz, na południe stąd, na miejscu katastrofy. Proszę, porozmawiaj z nim jak najszybciej.', 'Porozmawiaj z Obrońcą Aldarem na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9307, 'plPL', '<DEPRECATED>Współczucie', 'Pobliskie Jezioro Srebrnej Linii zostało skażone przez fragment statku, który do niego wpadł. To z kolei wywołało mutacje większości stworzeń w okolicy, a część z nich stała się wroga. Najgorsze są zmutowane lunozwierze.$B$BUdaj się na południe do Gąszczu Gniazdowego Lasu i dobij tyle tych nieszczęsnych stworzeń, ile zdołasz. To zabijanie z litości, $N, więc proszę, niech będzie szybkie i bezbolesne.', 'Zabij 14 zmutowanych lunozwierzy, a następnie wróć do Obrońcy Aldara na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Obrońcy Aldara w Świętym Gaju na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9308, 'plPL', '<DEPRECATED>Szczątki krwawego elfa?', 'Sądzisz, że leżą tu na ziemi zwłoki jednego z sin\'dorei – krwawego elfa. Wygląda na to, że padł ofiarą dzikich szponów co najmniej kilku zmutowanych lunozwierzy z gąszczu.$B$BPrzeszukując ciało, znajdujesz na jego szyi amulet na łańcuszku. Może zainteresuje on Obrońcę Aldara?', 'Zanieś amulet krwawego elfa Obrońcy Aldarowi na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9309, 'plPL', 'Zaginiony zwiadowca', 'Mamy już kilka niezależnych potwierdzeń niezwykłej aktywności na Grani Cienia.$B$BTo niepokojące; sądziliśmy, że dotychczasowe zwiady były dokładne. Jeden z moich zwiadowców wciąż nie złożył meldunku.$B$B$N, musisz udać się na południowy zachód, na drugi brzeg Jeziora Srebrnej Linii, odnaleźć Tolaana i sprawdzić, co go zatrzymało.', 'Odnajdź Tolaana na Grani Cienia w Dolinie Ammen i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(9311, 'plPL', 'Szpieg krwawych elfów', 'Mam plan. Musimy zabić ich przywódcę. Bez przełożonego może wycofają się, by przegrupować siły. Musimy tylko zyskać na czasie, dopóki naprawy nie zostaną ukończone.$b$bPotem Obrońca Aldar musi się o tym dowiedzieć. Zabij geodetkę, a potem wróć i opowiedz mu, co odkryliśmy.', 'Zabij geodetkę Candress, a następnie powiadom Obrońcę Aldara na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Obrońcy Aldara na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(9312, 'plPL', 'Emiter', '$N, gdy $gbadałeś:badałaś; Grań Cienia, Zhanaa bez przerwy mówiła o emiterze holograficznym. Może warto z nią porozmawiać.', 'Porozmawiaj z techniczką Zhanaa na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9313, 'plPL', 'Podróż do Lazurowej Strażnicy', 'Na wszystko, co dobre, $N, musisz natychmiast udać się do tej Lazurowej Strażnicy i porozmawiać z Dyvuunem!$B$BZ tej małej wysepki na zachód prowadzi ścieżka. Idź nią i przejdź przez Kryształowy Strumień, by dotrzeć na większą część wyspy. Trzymaj się dalej ścieżki, a trafisz do Lazurowej Strażnicy.$B$BSpróbuj ich przekonać, żeby przysłali nam pomoc i zapasy. Reszta z nas dołączy, gdy tylko będzie mogła.$B$BDziękuję, bez ciebie byśmy sobie nie poradzili!', 'Porozmawiaj z technikiem Dyvuunem w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9314, 'plPL', 'Wieści z Lazurowej Strażnicy', '$N! Kilka zmutowanych bestii rzuciło się na mnie i mam ranną nogę.$B$BWysłano mnie z Lazurowej Strażnicy na zwiad, gdy dostaliśmy wiadomość od Zhanaa. Proszę, czy $gmógłbyś:mogłabyś; porozmawiać w moim imieniu z opiekunką Chellan? Musi wiedzieć, ilu przybyszów spodziewać się w Lazurowej Strażnicy. Przejdź tu przez Kryształowy Strumień i idź dalej drogą, aż dotrzesz do Lazurowej Strażnicy.$B$BKoniecznie poproś ją też o miejsce, w którym możesz się zatrzymać.', 'Porozmawiaj z opiekunką Chellan w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9369, 'plPL', 'Odnowienie kryształów leczniczych', 'Jesteśmy draenei. Nasz statek się rozbił, a ponieważ mamy wielu rannych, najpilniejszą sprawą jest wyczerpanie naszych kryształów leczniczych. Musimy je szybko odnowić!$B$BNiestety, w tej chwili jedynym sposobem jest pozyskanie krwi miejscowych ciem z doliny. Ich krew będzie odpowiednim zamiennikiem.$B$BĆmy można spotkać w wielu miejscach doliny, ale najwięcej jest ich na północnym zachodzie.', 'Zdobądź 8 fiolek krwi ćmy od pobliskich ciem z Doliny i przynieś je Proenitusowi na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do Proenitusa na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(9371, 'plPL', 'Botaniczka Taerix', '$N, botaniczka Taerix potrzebuje twojej pomocy. Znajdziesz ją razem z jej uczniami na zachodzie, na zewnątrz statku.', 'Porozmawiaj z botaniczką Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9393, 'plPL', 'Szkolenie łowcy', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych łowców na Wyspie Słońcobieżców szkoli tropicielka Sallina. Porozmawiaj z Salliną i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BSallina – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z tropicielką Salliną, nauczycielką łowców, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9409, 'plPL', 'Pilna dostawa!', 'Skoro $gzebrałeś:zebrałaś; już wszystko, czego potrzeba do odnowienia kryształów leczniczych, chcę, żebyś $gdostarczył:dostarczyła; fiolki Zalduunowi, naszemu kapłanowi. Znajdziesz go przy rannych w centralnej komorze statku.', 'Dostarcz pakunek fiolek Zalduunowi na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9421, 'plPL', 'Szkolenie szamana', '', '', '', '', '', '', '', '', 0),
(9449, 'plPL', 'Zew ziemi', 'Nadszedł czas, $N. $GDojrzałeś:Dojrzałaś; do tego, by obcować bezpośrednio z duchami żywiołów tego świata.$B$BAle strzeż się. Wyczuwam, że sposób, w jaki przybyliśmy do tego świata, i jego niefortunne skutki rozgniewały duchy ziemi i zachwiały równowagę żywiołów.$B$BJeśli masz stworzyć swój totem ziemi, musisz najpierw porozmawiać z Duchem Doliny. Znajdziesz go w Świętym Gaju, ukrytym wśród wzgórz na północnym zachodzie.', 'Porozmawiaj z Duchem Doliny w Świętym Gaju w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9450, 'plPL', 'Zew ziemi', 'Równowaga żywiołów została zakłócona przez gwałtowne wtargnięcie draenei do Doliny. Wasza katastrofa rozwścieczyła duchy ziemi, które zwróciły się przeciw pozostałym żywiołom, przybyłym, by je uśmierzyć. Przekonasz się, że zrozumienie żywiołów przychodzi tylko wtedy, gdy wszystkie trwają w harmonii.$B$BDlatego to na tobie spoczywa przywrócenie równowagi. Za mną, w gaju, znajdziesz niespokojne duchy ziemi walczące z pozostałymi trzema żywiołami. Pomóż przywrócić równowagę.', 'Zabij 4 niespokojne duchy ziemi, a następnie wróć do Ducha Doliny w Świętym Gaju w Dolinie Ammen.', '', 'Wróć do Ducha Doliny w Świętym Gaju na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9451, 'plPL', 'Zew ziemi', 'Teraz dam ci cząstkę mojej fizycznej istoty, abyś $gmógł:mogła; stworzyć swój totem ziemi. Zanieś ją temu, kto cię tu przysłał.$B$BTy i ja będziemy związani na zawsze. Przez całe twoje życie siły ziemi będą do twojej dyspozycji. Równowaga nastąpi, gdy pod koniec twoich dni twoje kości powrócą do nas.$B$BKorzystaj z naszej mocy mądrze.', 'Dostarcz kryształ ziemi Firmanvaarowi na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9452, 'plPL', 'Lucjan czerwony – palce lizać!', 'Odkryłam, że w tych wodach roi się od lucjanów czerwonych, bardzo smacznych ryb. Siecią rybacką mogę złowić tyle, że wykarmię dziesiątki draenei! Niestety, niedawno, gdy zarzucałam sieć w rzece, zaatakowało mnie stworzenie zwane murlokiem i odniosłam rany, przez które nie mogę wykonywać swojej pracy. Potrzebuję pomocy!$B$BUżyj tej sieci rybackiej przy ławicach lucjanów czerwonych w Kryształowym Strumieniu na wschodzie, żeby złowić ryby.$B$BCo ty na to? Pamiętaj, żeby oddać mi sieć, kiedy skończysz.', 'Użyj draenejskiej sieci rybackiej, by złowić 10 lucjanów czerwonych. Po wykonaniu zadania oddaj zarówno ryby, jak i sieć Diktynnie na Wyspie Lazurowej Mgły.', '', 'Wróć do Diktynny przy Brodzie Ammen na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9453, 'plPL', 'Odnajdź Acteona!', '$GSpisałeś:Spisałaś; się wspaniale, $N. Nasz lud będzie wdzięczny za tę obfitość. Skoro tak, czy $gmógłbyś:mogłabyś; zanieść ten połów lucjanów czerwonych Acteonowi w Lazurowej Strażnicy?$B$BNie powinno być trudno go znaleźć, bo czeka na tę dostawę.', 'Dostarcz skrzynkę lucjanów czerwonych Acteonowi w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9454, 'plPL', 'Wielkie łowy na księżycowe jelenie', 'Zaczynasz wyrabiać sobie imię, $N. Może spróbujesz swoich sił w łowach?$B$BNa Draenorze nasi najwięksi łowcy polowali na zwierzę zwane talbukiem, przypominające tutejszego księżycowego jelenia.$B$BJeśli uważasz, że dość w tobie z draenei, ruszaj w dzicz i zabij tyle jeleni, by napełnić torbę mięsem.$B$BZnajdziesz je na pastwiskach na południe od Lazurowej Strażnicy. Uważaj na ich poroże!', 'Przynieś 6 polędwic z księżycowego jelenia Acteonowi w Lazurowej Strażnicy.', '', 'Wróć do Acteona w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9455, 'plPL', 'Dziwne znalezisko', 'Kryształ, który $gznalazłeś:znalazłaś; w ciele chuchra nocnego tropiciela, wygląda na fragment Exodaru. Może to wyjaśniać niezwykły wygląd i zachowanie niektórych zwierząt w tej okolicy.$B$BZanieś kryształ do Lazurowej Strażnicy. Egzarcha z pewnością zechce się dowiedzieć o tym odkryciu.', 'Dostarcz słabo świecący kryształ Egzarsze Menelaousowi w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9456, 'plPL', 'Nocni tropiciele – sprzątanie na wyspie 2...', 'Nie zamierzam szukać wymówek dla tego, co $gznalazłeś:znalazłaś;. To wyraźnie nasza wina. Dochodziły nas wieści o pokruszonych odłamkach kryształów pojawiających się w rzece na wschodzie, ale postanowiliśmy zignorować, co to oznacza. Teraz możemy albo siedzieć na tej wyspie i opłakiwać tragedię, która spadła na tę krainę, albo coś z tym zrobić i nie dopuścić, by się rozprzestrzeniła.$B$BJeśli masz do tego żołądek, chcę, żebyś $gwrócił:wróciła; w dzicz i $gzabił:zabiła; tylu zakażonych nocnych tropicieli, ilu zdołasz znaleźć.', 'Egzarcha Menelaous w Lazurowej Strażnicy prosi, żebyś $gzabił:zabiła; 8 zakażonych chuchr nocnego tropiciela.', '', 'Wróć do Egzarchy Menelaousa w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9461, 'plPL', 'Zew ognia', 'Musisz wiedzieć, że Prorok pytał o ciebie, gdy usłyszał o twoim sukcesie w próbie. Stworzenie twojego totemu ognia musi poczekać, aż z nim porozmawiasz.$b$bTo rzadki zaszczyt; musisz natychmiast udać się do Exodaru, by się z nim zobaczyć!', 'Odszukaj Proroka Velena w Skarbcu Świateł w Exodarze.', '', '', '', '', '', '', 0),
(9463, 'plPL', 'Cel leczniczy', 'Odkryłam, że pnącza smagaczy krążących po wyspie mają lecznicze, wzmacniające właściwości. Odpowiednio przetworzone dają się przerobić na silną maść leczniczą. Niestety, przez Lazurową Strażnicę przewija się tak wielu rannych draenei, że wciąż jej nam brakuje.$B$BNaszego delikatnego gościa znaleziono rannego i nieprzytomnego nad Kryształowym Strumieniem zaledwie wczoraj. Jeśli przyniesiesz mi pnącza, może zdołamy ją uratować.$B$BKorzeniowe sidlarze znajdziesz na południe i na wschód od Lazurowej Strażnicy.', 'Anachoretka Fateema w Lazurowej Strażnicy chce, żebyś $gprzyniósł:przyniosła; jej 8 pnączy korzeniowego sidlarza.', '', 'Wróć do Anachoretki Fateemy w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9464, 'plPL', 'Zew ognia', 'Znów zostaniesz $gpoddany:poddana; próbie, a tym razem musisz zrozumieć chaotyczny żywioł ognia, jeśli masz stworzyć totem, który okiełzna jego energię.$B$BNa północnym wschodzie, na wybrzeżu, leży święte miejsce ognia zwane Żarzystą Polaną. Wśród jej spalonych drzew stoi Porywczak, żywiołak ognia o wielkiej mocy – to z nim musisz porozmawiać.$B$BIdź do niego teraz i niech duchy żywiołów Azeroth będą z tobą.', 'Porozmawiaj z Porywczakiem na Żarzystej Polanie na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9465, 'plPL', 'Zew ognia', 'Jeden z moich braci, Hauteur, postradał zmysły – bez wątpienia przez katastrofę waszego statku. Zaczął żądać, by miejscowe sowostwory oddawały mu cześć.$B$BTak dalej być nie może! Nikt z nas nigdy nie podszywałby się pod boga! To na tobie spoczywa przywrócenie równowagi.$B$BNajpierw musisz odzyskać ich rytualną pochodnię, którą zabrały oszalałe dziczołaki w Warowni Cichej Sosny na zachodzie.$B$BPrzynieś mi tę pochodnię.', 'Odzyskaj rytualną pochodnię i zanieś ją Porywczakowi na Żarzystej Polanie na Wyspie Lazurowej Mgły.', '', 'Wróć do Porywczaka na Żarzystej Polanie na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9467, 'plPL', 'Zew ognia', 'Sowostwory z Nory Księżycowego Skrzydła na Wyspie Srebrnej Mgły, daleko na południowym zachodzie, dały się omamić i uwierzyły, że Hauteur jest bogiem, któremu należy się cześć. W rzeczywistości to upadły żywiołak, którego trzeba uwolnić od cierpienia. Ta pochodnia jest kluczem do jego upadku.$B$BHauteur regularnie żąda, by sowostwory paliły na jego cześć kukłę. Kiedy więc ją podpalisz, przybędzie. Zabij go i przynieś mi jego prochy. Potem użyj kuli z sakwy, którą ci dam, by wrócić tu do mnie.', 'Zdobądź prochy Hauteura, a następnie zanieś je razem z rytualną pochodnią Porywczakowi na Żarzystej Polanie na Wyspie Lazurowej Mgły. Pamiętaj, że gdy już zdobędziesz prochy, możesz użyć Kuli powrotu, by przenieść się z powrotem do Porywczaka.', '', 'Wróć do Porywczaka na Żarzystej Polanie na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9468, 'plPL', 'Zew ognia', '$GDokonałeś:Dokonałaś; tu dziś wielkiej rzeczy, dążąc do zrozumienia swojej więzi z płomieniem. Pamiętaj, by zawsze traktować go z najwyższym szacunkiem, bo inaczej się sparzysz.$B$BZachowałem dla ciebie część prochów Hauteura. Użyj ich do stworzenia swojego totemu ognia i pamiętaj o wszystkim, czego się $gnauczyłeś:nauczyłaś;, zdobywając je.$B$BA teraz wróć do Tuluuna.', 'Dostarcz prochy Hauteura Tuluunowi w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9473, 'plPL', 'Alternatywa dla alternatywy', 'Z dziewczyną jest zbyt źle, by same maści mogły pomóc. Może jest inny sposób...$B$BLas Lazurowej Mgły kryje wiele tajemnic, a jedną z nich jest rzadka roślina zwana lazurową lwią paszczą, którą niektórzy uważają za panaceum – lek na wszystko.$B$BRozpoznasz ją po tym, że wyraźnie odróżnia się od innych roślin Lazurowej Mgły i musi rosnąć u stóp lazurowych sosen. Pośpiesz się!$B$BI, $N, uważaj na korzeniowe młocarze w tej okolicy, bo żywią się lwią paszczą.', 'Daedal w Lazurowej Strażnicy chce, żebyś $gprzyniósł:przyniosła; mu 5 cebulek lazurowej lwiej paszczy.', '', 'Wróć do Daedala w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9505, 'plPL', 'Proroctwo Velena', 'Prorok mówił o tym dniu: że na tej wyspie, w tym nowym świecie, odnajdą nas nasi sojusznicy.$B$B„Zostaniemy wystawieni na próbę. Zażądają, byśmy zapłacili za grzechy naszych ojców...”$B$BWtedy nie rozumiałem znaczenia jego słów, ale widząc tę istotę i jej reakcję na nas, zaczynam je pojmować. Skażenie naszego ludu dało się odczuć nawet tutaj.$B$BUdaj się na południe. To tam znaleźliśmy tę istotę. Odszukaj jej pobratymców i opowiedz im o naszym ludzie.', 'Daedal chce, żebyś $gudał:udała; się na południe i $godszukał:odszukała; lud, o którym wspomniała ranna istota.', '', '', '', '', '', '', 0),
(9506, 'plPL', 'Skromny początek', 'Jestem admirał Odesyus z Dowództwa floty Przymierza. Nasz statek musiał zawinąć do waszej wyspy z powodu swego rodzaju plagi. Aż wstyd o tym mówić, ale gobliny zdołały jakoś ukryć się w ładowniach obu moich okrętów.$B$BZeszłej nocy, gdy większość załogi spała pod pokładem, uderzyły!$B$BCo dziwniejsze, zabrały nasz sprzęt nawigacyjny i uciekły ze statku!$B$BZniknęły w zaroślach na wschód stąd. Czy zechcesz poszukać naszego sprzętu? To byłby wymowny gest.', 'Admirał Odesyus w Przystani Odesyusa chce, żebyś $godzyskał:odzyskała; kompas morski i mapę morską skradzione przez spółkę Gitgeszeft.', '', 'Wróć do admirała Odesyusa w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9507, 'plPL', '<DEPRECATED>Z biurka magnata Razdunka', 'Według tych planów gobliny przybyły tu po kryształowe szczątki Exodaru. Wygląda na to, że zamierzają ogołocić wyspę z kryształów, a po zakończeniu roboty porwać dwa okręty Przymierza zakotwiczone u brzegu.$B$BChyba warto zanieść te plany admirałowi Odesyusowi.', 'Zanieś ściśle tajne plany spółki Gitgeszeft admirałowi Odesyusowi w Przystani Odesyusa.', '', '', '', '', '', '', 0),
(9512, 'plPL', 'Ogromne gumbo Ciastka', 'Admirał ma rację, zaradna z ciebie dusza. Może byś tak $gpomógł:pomogła; Ciastkowi?$B$BJak znów podam załodze kurczaka na obiad, to na pewno wyląduję w karcerze.$B$BWidziałem, że wzdłuż całego wybrzeża łażą pełzacze – pełno pełzaczy! Przynieś mi mięso z pełzaczy, a będę ci dozgonnie wdzięczny.$B$BPomożesz nawróconemu piratowi?', '„Ciastek” McCienkisos w Przystani Odesyusa chce, żebyś $gprzyniósł:przyniosła; mu 6 porcji mięsa pomykającego pełzacza.$B', '', 'Wróć do „Ciastka” McCienkisosa w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9513, 'plPL', 'Odzyskanie ruin', 'Choć niektórzy uznają nasze obecne położenie za niefortunny zbieg okoliczności, ja czuję, że znaleźliśmy się tu nie bez powodu. Niewidzialna ręka losu popchnęła nas w tę stronę. Z czasem powód stanie się jasny.$B$BNa zachodzie leży starożytne miasto nocnych elfów, dziś w ruinie i opanowane przez nagi. Nie mogę bezczynnie patrzeć, jak nagi kalają ziemie moich przodków.$B$B$GPokazałeś:Pokazałaś;, na co cię stać. Oddaj cześć mojemu ludowi i oczyść ruiny z nieproszonych mieszkańców.', 'Kapłanka Kyleen Il\'dinare w Przystani Odesyusa na Wyspie Lazurowej Mgły chce, żebyś $gzabił:zabiła; 5 siepaczy Gniewnej Łuski, 5 nag Gniewnej Łuski i 5 syren Gniewnej Łuski.', '', 'Wróć do kapłanki Kyleen Il\'dinare w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9514, 'plPL', 'Tablica pokryta runami', 'Nie potrafisz odczytać żadnego z symboli na tablicy. Może kapłanka zdoła odszyfrować tajemnicze runy.', 'Zanieś tablicę pokrytą runami kapłance Kyleen Il\'dinare w Przystani Odesyusa na Wyspie Lazurowej Mgły.$B', '', '', '', '', '', '', 0),
(9515, 'plPL', 'Watażka Sriss\'tiz', 'Inwazja nag byłaby katastrofą, $N. Widziałam, do czego zdolne są nagi, i nie chciałabym, żeby takie nieszczęście spotkało jakąkolwiek istotę. Gdybym miała zgadywać, ten watażka Sriss\'tiz ukrywa się w jakiejś jaskini – pewnie gdzieś na wybrzeżu na zachodzie.$B$BOdnajdź watażkę Sriss\'tiza i połóż kres jego panowaniu.', 'Kapłanka Kyleen Il\'dinare w Przystani Odesyusa na Wyspie Lazurowej Mgły chce, żebyś $gzabił:zabiła; watażkę Sriss\'tiza.', '', 'Wróć do kapłanki Kyleen Il\'dinare w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9523, 'plPL', 'Cenne i kruche rzeczy wymagają ostrożności', 'Kapłanka mówi, że ruiny na zachodzie to pozostałości cywilizacji nocnych elfów. To mi przypomniało, co zawsze powtarzał mój tatko o ruinach nocnych elfów: „Synku, gdzie tylko zobaczysz ruiny nocnych elfów, tam na pewno niedaleko będą relikwie nocnych elfów”.$B$BNo i jakim byłbym krasnoludem, gdybym nie najął pierwszej napotkanej osoby, żeby wykopała dla mnie relikwie nocnych elfów? No, ruszaj się!', 'Archeolog Adamant Żelaznosercy w Przystani Odesyusa na Wyspie Lazurowej Mgły chce, żebyś $gprzyniósł:przyniosła; mu 8 starożytnych relikwii.', '', 'Wróć do archeologa Adamanta Żelaznosercego w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9527, 'plPL', 'Wszystko, co pozostało', 'Przez wiele lat żyliśmy w pokoju wśród sowostworów z tej wyspy. Możesz sobie wyobrazić moje zdumienie, gdy wpadły na plażę i nas zaatakowały.$B$BWalczyłem zębami i pazurami, ale łatwo mnie obezwładniły. Tracąc przytomność od zadanych mi okrutnych ciosów, modliłem się, by moja rodzina nie cierpiała.$B$BGdy się ocknąłem, wszędzie panowała cisza. Piasek przesiąkł na czerwono krwią – ich krwią. Pożarto ich w całości.$B$BNie zależy mi na zemście, $N. Proszę tylko, by ich szczątki wróciły do mnie, bym mógł je godnie pochować.', 'Cowlen na Wyspie Lazurowej Mgły chce, żebyś $godzyskał:odzyskała; szczątki jego rodziny.', '', 'Wróć do Cowlena na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9528, 'plPL', 'Wołanie o pomoc', 'Kilka tygodni temu na moją rodzinę napadły murloki i lunozwierze z tej wyspy. Udało mi się uciec, ale chyba zarówno matka, jak i ojciec zginęli. Nie wiem, co teraz zrobię, ale muszę spróbować wrócić do domu – albo do tego, co z niego zostało... Pomożesz mi przedostać się przez las?', 'Odprowadź Magwin przez wyspę do jej domu.', 'Magwin bezpiecznie odprowadzona', 'Wróć do Cowlena na Wyspie Srebrnej Mgły u wybrzeży Wyspy Lazurowej Mgły.', '', '', '', '', 0),
(9530, 'plPL', 'Zielona przykrywka', 'Od pewnego czasu się nad tym zastanawiałem, a to dowodzi, że miałem rację.$B$BJest wśród nas zdrajca.$B$BPlany, które zostawiły gobliny, dokumentują spisek. Ponieważ nie wiem, kto to może być, będę potrzebował twojej pomocy, by go znaleźć. Nie mogę ufać nikomu z mojej załogi.$B$BŻeby to się udało, potrzebuję wydrążonego drzewa i liści. Drzewa poszukaj przy drwalach na północ stąd. Liście musisz znaleźć $gsam:sama;. Przeszukaj las.', 'Admirał Odesyus w Przystani Odesyusa na Wyspie Lazurowej Mgły chce, żebyś $gprzyniósł:przyniosła; mu wydrążone drzewo i 5 stert liści.', '', 'Wróć do admirała Odesyusa w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9531, 'plPL', 'Drzewa mają uszy', 'Według planów zdrajca i przywódca goblinów, Geezle, mają się spotkać w zatoczce na zachodniej wyspie. Musisz być na tym spotkaniu, $N.$B$BPamiętasz drzewo i liście? Założysz je na siebie! To doskonałe przebranie.$B$BIdź do zatoczki i poszukaj flagi nag. Jeśli flaga tam jest, znaczy to, że zaplanowano spotkanie. Gdy zobaczysz flagę, użyj zestawu do przebrania i czekaj. W końcu zdrajca się zjawi. Pozwól im dokończyć rozmowę, a potem wróć do mnie i powiedz, kim jest ten łajdak.', 'Admirał Odesyus w Przystani Odesyusa na Wyspie Lazurowej Mgły chce, żebyś $gpodpatrzył:podpatrzyła; spotkanie Geezle\'a ze zdrajcą.$B$BWróć do niego, gdy poznasz tożsamość zdrajcy.', '', 'Wróć do admirała Odesyusa w Przystani Odesyusa na Wyspie Lazurowej Mgły.', 'Zdrajca zdemaskowany', '', '', '', 0),
(9537, 'plPL', 'Bez litości dla gnoma', 'Iskra musi stanąć przed sądem!$B$BZejdź na plażę i znajdź tego zakłamanego gnoma. Gdy go znajdziesz, wyciągnij z niego wszystko, co się da!$B$BSkoro wysoki rangą urzędnik Przymierza dopuścił się zdrady, kto wie, ilu jeszcze jest skorumpowanych?$B$BI, $N, w razie potrzeby użyj siły...$B', 'Admirał Odesyus w Przystani Odesyusa chce, żebyś $godebrał:odebrała; wiadomość zdrajcy inżynierowi „Iskrze” Nadszlifowi.', '', 'Wróć do admirała Odesyusa w Przystani Odesyusa na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9538, 'plPL', 'Nauka języka', 'Chyba to rozgryzłem, $N!$B$B<Aurren wskazuje totem.>$B$BWszystko, co musimy wiedzieć o języku furbolgów Cichej Sosny, jest wyryte na ich totemach. Wystarczy podstawowe zrozumienie, jak działają ich symbole, a będziemy mogli badać totemy i nauczyć się porozumiewać z furbolgami.$B$BSpisałem na tym pergaminie podstawy układu symboli. Przestudiuj go, a potem zbadaj totem. Powinien zaprowadzić cię do kolejnego totemu językowego.$B$BPorozmawiaj z Arugoo, gdy wrócisz jako $gwykształcony:wykształcona; $r!', 'Przeczytaj elementarz języka furbolgów Cichej Sosny, który dał ci Aurren, i zbadaj Totem Akida w Lazurowej Strażnicy.', 'Elementarz języka furbolgów Cichej Sosny przeczytany', 'Wróć do Totemu Akida na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9539, 'plPL', 'Totem Coo', 'Zaczynasz odczytywać totem, z trudem wymawiając niezgrabne słowa i zwroty. Powoli w twojej głowie zaczynają się układać słowa. Masz wrażenie, że totem każe ci wejść na pobliskie wzgórze na północnym wschodzie.', 'Odnajdź Totem Coo, korzystając z otrzymanych wskazówek.', '', '', '', '', '', '', 0),
(9540, 'plPL', 'Totem Tikti', 'Zaczynasz odczytywać totem i słowa oraz zwroty przychodzą ci już łatwiej. W twojej głowie zaczynają się układać słowa. Masz wrażenie, że totem każe ci przejść przez Kryształowy Strumień na wschodzie. Może twój cel leży na drugim brzegu rzeki.', 'Odnajdź Totem Tikti, korzystając z otrzymanych wskazówek.', '', '', '', '', '', '', 0),
(9541, 'plPL', 'Totem Yor', 'Symbole na tym totemie odczytujesz już znacznie szybciej. Wzory i obrazy zlewają się w znajome słowa. Masz niemal pewność, że totem wskazuje ci drogę na południe, w dół rzeki. Coś leży na samym dnie rzeki.', 'Odnajdź Totem Yor, korzystając z otrzymanych wskazówek.', '', '', '', '', '', '', 0),
(9542, 'plPL', 'Totem Vark', 'Symbole na totemach nie są już dla ciebie niezrozumiałe. Totem Yor czytasz równie łatwo jak w ojczystym języku.$B$BZnaki wskazują kolejne legowisko furbolgów, prosto na zachód stąd. Bez trudu odczytujesz język totemu i wiesz, że twoim celem jest Wioska Szczecinołapych. Yor cię poprowadzi, ale jeśli zabłądzisz, pamiętaj, że do celu zaprowadzi cię starożytna elfia droga biegnąca przez las na zachód.', 'Odnajdź Totem Vark, korzystając z otrzymanych wskazówek.', '', '', '', '', '', '', 0),
(9544, 'plPL', 'Proroctwo Akida', 'Obrazy na tym totemie przedstawiają wojnę między plemionami furbolgów Cichej Sosny i Szczecinołapych. Ryty pokazują, że Szczecinołapi dopuścili się niegodziwych czynów wobec furbolgów z Cichej Sosny.$B$BPośród chaosu zaczęło się spełniać proroctwo: powstanie bohater – nie z krwi furbolgów – i ocali plemię Cichej Sosny.$B$BZabijaj furbolgi ze Szczecinołapych w Wiosce Szczecinołapych i zabieraj im klucze. Użyj kluczy, by uwolnić jeńców Cichej Sosny. Gdy uwolnisz wszystkich, wróć do Arugoo z Cichej Sosny!$B', 'Uwolnij 8 jeńców Cichej Sosny z klatek w Wiosce Szczecinołapych. Gdy wykonasz to zadanie, wróć do Arugoo z Cichej Sosny w Lazurowej Strażnicy.', '', 'Wróć do Arugoo z Cichej Sosny w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', 'Uwolniony jeniec Cichej Sosny', '', '', '', 0),
(9546, 'plPL', 'Spełnienie obietnicy', 'Proroctwo mówiło o kimś, kto powstanie i wyzwoli nas z ucisku Szczecinołapych – o tym, że same duchy zwiastują przybycie tego bohatera.$B$BI oto $gprzybyłeś:przybyłaś;.$B$BKorzę się przed tobą, $gwielki:wielka;. Błagam cię, ocal nasze młode. Szczecinołapi porwali je, gdy straciliśmy czujność. Znajdziesz je w klatkach w Wiosce Szczecinołapych, na południowym zachodzie. Klucze do klatek mają furbolgi ze Szczecinołapych. Zabij ich i zabierz klucze. Uwolnij moich pobratymców.', 'Arugoo z Cichej Sosny prosi, żebyś $guwolnił:uwolniła; 8 jeńców Cichej Sosny z klatek w Wiosce Szczecinołapych.', '', 'Wróć do Arugoo z Cichej Sosny na Wyspie Lazurowej Mgły.', 'Uwolniony jeniec Cichej Sosny', '', '', '', 0),
(9559, 'plPL', 'Warownia Cichej Sosny', '$GObiecany:Obiecana;, musisz udać się na północ, do domu mojego ludu – Warowni Cichej Sosny. To tam czeka cię najtrudniejsza próba.$B$BIdź już, najwyższy wódz Cicha Sosna oczekuje twojego przybycia.', 'Porozmawiaj z najwyższym wodzem Cichą Sosną w Warowni Cichej Sosny.', '', '', '', '', '', '', 0),
(9560, 'plPL', 'Bestie apokalipsy!', 'Polowaliśmy z bratem w lasach na wschodzie, gdy zaatakowały nas dziwne, owadopodobne bestie. Takich wynaturzeń nigdy dotąd nie widziano na Lazurowej Mgle! Czyżby były zwiastunem nadchodzącej apokalipsy? Apokalipsy, której TOBIE jest pisane zapobiec?$B$BJeśli naprawdę jesteś $gObiecanym:Obiecaną;, zabijesz stworzenia apokalipsy... i przyniesiesz mi ich skóry. Z ich skór zrobię pancerz o wielkiej mocy!$B$BZnajdziesz je na wschodzie, za drogą.', 'Moordo w Warowni Cichej Sosny na Wyspie Lazurowej Mgły chce, żebyś $gprzyniósł:przyniosła; mu 8 skór pustoszycieli.', '', 'Wróć do Moordo w Warowni Cichej Sosny na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9562, 'plPL', 'Murloki... Czemu tu? Czemu teraz?', 'Nastały mroczne dni, $gObiecany:Obiecana;. Nawet murloki kopią nas po ogonach – dosłownie. Niestety ucierpiała nie tylko moja duma.$B$BNasze stosunki z murlokami Mułopłetwych zawsze były napięte, ale nigdy nie przypuszczaliśmy, że będą miały czelność nas zaatakować i obrabować nasze spiżarnie! Idź na zachód, na Zamulony Brzeg, i odzyskaj skradzione zapasy!$B$BA jeśli zobaczysz murloka o ciemnej skórze, któremu między błoniastymi palcami utkwiła kępka białego futra...', 'Gurf w Warowni Cichej Sosny na Wyspie Lazurowej Mgły chce, żebyś $godzyskał:odzyskała; 5 worków ziarna Cichej Sosny.', '', 'Wróć do Gurfa w Warowni Cichej Sosny na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9564, 'plPL', 'Godność Gurfa', 'Odzyskujesz kępkę futra, którą Gurf „zgubił” w walce z murlokami. Zanieś futro Gurfowi i powiedz mu, że groźna Murgurgula nie żyje.', 'Zanieś godność Gurfa Gurfowi w Warowni Cichej Sosny na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9565, 'plPL', 'Przeszukaj Warownię Cichej Sosny', 'Jako najwyższego wodza najbardziej niepokoi mnie źródło skażenia w Warowni Cichej Sosny.$B$BDlaczego dziczołaki – niegdyś nasi sojusznicy – nas zaatakowały? Dlaczego zagnieździły się w Warowni Cichej Sosny?$B$BMoże w środku znajdzie się odpowiedź. Przeszukaj Warownię Cichej Sosny w poszukiwaniu wskazówek, co jest źródłem skażenia.', 'Przeszukaj Warownię Cichej Sosny w poszukiwaniu wskazówek.', '', '', '', '', '', '', 0),
(9566, 'plPL', 'Krwawe kryształy', 'Na pierwszy rzut oka kryształ wygląda na fragment Exodaru. Coś jednak poszło z nim bardzo nie tak – jest krwistoczerwony i szybko rozpuszcza się w wodzie, z której korzystają mieszkańcy jaskini.$B$BTo może tłumaczyć niezwykłą agresję stworzeń na Lazurowej Mgle. Wróć z tymi wieściami do najwyższego wodza Cichej Sosny.$B', 'Porozmawiaj z najwyższym wodzem Cichą Sosną w Warowni Cichej Sosny.', '', '', '', '', '', '', 0),
(9570, 'plPL', 'Kurken się czai', 'Gdy kryształowa burza ucichła, w naszej wiosce pojawiła się mityczna bestia. Sprowadzona przez najeźdźców-dziczołaki, bestia ta, Kurken, obróciła naszą wioskę w ruinę. Wielu z Cichej Sosny zginęło z ręki tego potwora, broniąc naszych ziem, i od tamtej pory wielu straciło życie, próbując go poskromić.$B$BW moich wizjach widziałem kogoś, kto pokonał Kurkena. Tym kimś musisz być ty, $N. Jesteś naszą jedyną nadzieją. Wejdź do Warowni Cichej Sosny i zabij Kurkena. Przynieś mi jego skórę jako dowód dokonanego czynu.$B', 'Kurz Objawiciel w Warowni Cichej Sosny na Wyspie Lazurowej Mgły chce, żebyś $gzabił:zabiła; Kurkena i $gprzyniósł:przyniosła; skórę Kurkena.', '', 'Wróć do Kurza Objawiciela w Warowni Cichej Sosny na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9571, 'plPL', 'Skóra Kurkena', 'Zanieś skórę Kurkena Moordo, po drugiej stronie wioski. Zrobi z niej przedmiot, jaki sobie wybierzesz.$B', 'Dostarcz skórę Kurkena Moordo w Warowni Cichej Sosny.', '', '', '', '', '', '', 0),
(9573, 'plPL', 'Wódz Oomooroo', 'Jestem Cicha Sosna Młodszy, dziedzic spuścizny Cichej Sosny. Jak widzisz, moi obrońcy zastawili śmiertelną pułapkę na szalejące dziczołaki, które atakują z wnętrza Warowni Cichej Sosny. Tu, na zewnątrz, potrafimy je powstrzymać, ale żadnemu z moich obrońców nie udało się przeniknąć do warowni. Gdyby udało ci się dostać do środka i zabić ich przywódcę, może zyskalibyśmy okazję do ataku!$B$BZnajdź wodza Oomooroo i zniszcz go. Zabij też wszystkie oszalałe dziczołaki, które napotkasz w środku.', 'Cicha Sosna Młodszy w Warowni Cichej Sosny na Wyspie Lazurowej Mgły chce, żebyś $gzabił:zabiła; wodza Oomooroo i 9 oszalałych dziczołaków.$B', '', 'Wróć do Cichej Sosny Młodszego w Warowni Cichej Sosny na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9582, 'plPL', 'Siła pojedynczego ostrza', 'Gdy statek się rozbił, nasza menażeria rozpierzchła się po plażach na północnym wschodzie wyspy. Dostałam klucz do klatki, w której zamknięto jeden z groźniejszych okazów – śmiercionośnego pustoszyciela. To stworzenie ma słaby pancerz, ale jest odporne na większość magii. Trzeba je zabić zwykłym ostrzem.$b$bWeź ten klucz i uwolnij stworzenie zarówno z więzienia, jak i od cierpienia. Nie możemy dopuścić, by uciekło i jeszcze bardziej zaszkodziło tutejszej przyrodzie, niż my już to zrobiliśmy.', 'Otwórz klatkę pustoszyciela i zabij śmiercionośnego pustoszyciela, a następnie wróć do Ruady w Lazurowej Strażnicy na Lazurowej Mgle.', '', 'Wróć do Ruady w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9586, 'plPL', 'Pomóż Tavarze', 'Tavara, jedna z naszych zielarek, już zbyt długo nie wraca z wyprawy po zioła. Obawiam się, że jest ranna i potrzebuje pomocy, a sam nie mogę jej szukać.$b$bProszę, odnajdź ją i w razie potrzeby ulecz, $gbracie:siostro;. Gdy opuszczała Lazurową Strażnicę, zmierzała na wschód, w stronę gorących źródeł.', 'Guvan w Lazurowej Strażnicy chce, żebyś $godnalazł:odnalazła; Tavarę i $guleczył:uleczyła; jej rany.', '', 'Wróć do Guvana w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', 'Ulecz Tavarę', '', '', '', 0),
(9595, 'plPL', 'Panowanie', '$GWybrałeś:Wybrałaś; ścieżkę maga, musisz więc nauczyć się panowania nad sobą. Magia pozbawiona kontroli może wypaczać dusze i niszczyć światy.$b$bBy w pełni to zrozumieć, musisz stanąć twarzą w twarz z kimś, kogo magia pochłonęła. Udaj się na plaże na północno-zachodnim wybrzeżu Wyspy Lazurowej Mgły i użyj zaklęć, by przetrzebić murloki. Taki pokaz mocy przyciągnie uwagę czającej się tam złej siły – upiora maga quel\'dorei. Pokonaj go.$b$bGdy skończysz, odszukaj Bati w Skarbcu Świateł w Exodarze.', 'Zabijaj murloki na Zamulonym Brzegu, by przywołać upiora maga quel\'dorei, a następnie go zniszcz. Potem porozmawiaj z Bati w Skarbcu Świateł w Exodarze.', '', 'Wróć do Bati w Skarbcu Świateł w Exodarze.', '', '', '', '', 0),
(9602, 'plPL', 'Zbaw ich ode złego...', 'Musisz przekazać te informacje swojemu ludowi, $N. Choć twoje odważne czyny z pewnością spowolniły plany Kael\'thasa i jego mrocznego pana, ataki bez wątpienia będą trwać.$B$BZanieś wiadomość zdrajcy swoim przywódcom. Muszą sami ją zobaczyć. Może lepiej zrozumieją część tego, co w niej zapisano.', 'Dostarcz wiadomość zdrajcy Egzarsze Menelaousowi w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9612, 'plPL', 'Z serca dziękuję!', '$GOcaliłeś:Ocaliłaś; mi życie, $N! Bardzo ci dziękuję! Gdyby nie ty, ta bestia rozszarpałaby mnie na strzępy.$B$BJeśli zobaczysz egzarchę w Lazurowej Strażnicy, opowiedz mu, czego $gdokonałeś:dokonałaś;. Na pewno ucieszy się z takich wieści!', 'Porozmawiaj z Egzarchą Menelaousem w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9616, 'plPL', 'Bandyci!', 'Wygląda to na księgę nagród za głowy. Nie rozumiesz języka krwawych elfów, ale zauważasz rysunek przedstawiający martwego draenei, uśmiechniętego krwawego elfa stojącego nad zwłokami i symbol czegoś, co wydaje się jakąś walutą krwawych elfów.$B$BWyznaczyli nagrodę za głowy draenei! Musisz powiadomić egzarchę.', 'Zanieś wiadomość krwawych elfów Egzarsze Menelaousowi w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9622, 'plPL', 'Ostrzeż swój lud', 'Warownia jest ocalona i wkrótce mój lud wróci do domu przodków. Proroctwo się spełniło i dla Cichej Sosny zaczyna się nowa era dobrobytu.$B$BLękam się jednak, że nad twoim ludem zbierają się ciemne chmury. Pozostały pytania bez odpowiedzi – wizje proroctwa, których nikt jeszcze nie ujrzał.$B$BWróć do swoich przywódców i opowiedz im, co tu $gwidziałeś:widziałaś;.$B$BA jeśli kiedykolwiek będziesz potrzebować pomocy Cichej Sosny, $gObiecany:Obiecana;, wystarczy, że poprosisz.', 'Porozmawiaj z Egzarchą Menelaousem w Lazurowej Strażnicy.', '', '', '', '', '', '', 0),
(9623, 'plPL', 'Czas dorosnąć', '$GPrzetrwałeś:Przetrwałaś; dzicz naszego nowego domu i $gpokazałeś:pokazałaś;, że przewyższasz innych. Uważam, że $gdojrzałeś:dojrzałaś; już, by wesprzeć tych, którzy walczą na pierwszej linii na Wyspie Krwawej Mgły. Ręce Argusa przyda się ktoś taki jak ty.$B$BZgłoś się do Toralliusa Poganiacza. Znajdziesz go przed Exodarem, gdzie dogląda elekków. Przekaż mu te rozkazy, a skieruje cię do nowych obowiązków na Wyspie Krwawej Mgły.', 'Egzarcha Menelaous w Lazurowej Strażnicy prosi, żebyś $gdostarczył:dostarczyła; rozkazy egzarchy Toralliusowi Poganiaczowi, który stoi przed Exodarem.', '', '', '', '', '', '', 0),
(9625, 'plPL', 'Elekki to poważna sprawa', 'Czy on oszalał? Powierzać coś takiego jakiemuś bezimiennemu żółtodziobowi!$B$BZapamiętaj sobie, $gmały:mała;: nigdy nie będzie z ciebie członek Ręki Argusa! Brak ci ikry!$B$BNo cóż, tym razem chyba muszę mu ustąpić. Porozmawiaj z Vorkhanem przy Przeprawie Kessela na Wyspie Krwawej Mgły. Idź po prostu drogą na północ, a gdy się rozwidli, trzymaj się dalej północy.', 'Porozmawiaj z Vorkhanem Pasterzem Elekków na Wyspie Krwawej Mgły.', '', '', '', '', '', '', 0),
(9672, 'plPL', 'Dziedzictwo krwawej klątwy', 'Drogi przyjacielu,$B$BRęka mi drży, gdy piszę ten list. Modlę się, by dotarł do ciebie na czas.$B$BZeszłej nocy w moim namiocie ukazał mi się Edward Hanes, kapitan statku „Utracona Nadzieja”. Ten sam Edward Hanes, który zmarł na szkorbut 20 lat temu.$B$BTa zjawa opowiedziała mi historię, od której zadrżało mi serce. Historię, którą musisz usłyszeć, i misję, którą musisz wypełnić. Zrobisz to? Odszukasz Edwarda na Wyspie Blizny Żmija, na północny wschód od twojej bazy?$B$BZ pozdrowieniami,$B$BAdmirał Odesyus$B', 'Admirał Odesyus prosi, żebyś $godnalazł:odnalazła; kapitana Edwarda Hanesa i z nim $gporozmawiał:porozmawiała;.', '', '', '', '', '', '', 0),
(9676, 'plPL', 'Szkolenie paladyna', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych paladynów na Wyspie Słońcobieżców szkoli Jesthenis Słońcobij. Porozmawiaj z Jesthenisem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BTwój nauczyciel – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Jesthenisem Słońcobijem, nauczycielem paladynów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9751, 'plPL', 'Dziedzictwo krwawej klątwy', 'Zeszłej nocy w moim namiocie ukazał mi się Edward Hanes, kapitan statku „Utracona Nadzieja”. Ten sam Edward Hanes, który zmarł na szkorbut 20 lat temu.$B$BTa zjawa opowiedziała mi historię, od której zadrżało mi serce. Historię, którą musisz usłyszeć, i misję, którą musisz wypełnić. Zrobisz to? Odszukasz Edwarda na Wyspie Blizny Żmija, na północny wschód od Krwawej Strażnicy?$B', 'Admirał Odesyus prosi, żebyś $godnalazł:odnalazła; kapitana Edwarda Hanesa i z nim $gporozmawiał:porozmawiała;.', '', '', '', '', '', '', 0),
(9798, 'plPL', 'Plany krwawych elfów', 'Te plany wydają się ważne. Zanieś je Obrońcy Aldarowi na miejscu katastrofy.', 'Zanieś plany krwawych elfów Obrońcy Aldarowi na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(9799, 'plPL', 'Botaniczna praca w terenie', 'Pola Ammen na zachodzie to główne miejsce rozmnażania się miejscowych smagaczy. Skoro wody gruntowe skaziło pobliskie jezioro, botaniczka Taerix obawia się, że smagacze nie zdołają odbudować swojej populacji, gdy już oczyścimy jezioro.$B$BIdź na Pola Ammen i zerwij dla mnie kilka skażonych kwiatów, żebym mogła im się przyjrzeć i sprawdzić, co da się zrobić. Rozpoznasz je po nietypowych czerwonych płatkach.', 'Zbierz 3 skażone kwiaty i zanieś je uczennicy Vishael na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do uczennicy Vishael na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(10302, 'plPL', 'Niestabilne mutacje', 'Napromieniowane rdzenie energetyczne z Exodaru sieją spustoszenie w tutejszym środowisku. Najbardziej widocznym skutkiem jest pojawienie się dziwnych stworzeń, które zdają się wyrastać w ich pobliżu.$b$bByć może zdołamy im jakoś pomóc, ale teraz jest ich po prostu za dużo, byśmy mogli sobie z nimi poradzić.$b$bChciałabym, żebyś $gwyruszył:wyruszyła; i nieco je $gprzetrzebił:przetrzebiła;. Może, gdy się nad tym zastanowię, wpadnę na inny pomysł.', 'Zabij 8 niestabilnych mutacji, a następnie wróć do botaniczki Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', 'Wróć do botaniczki Taerix na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', 0),
(10303, 'plPL', 'Krwawe elfy', 'Musisz usunąć... zagrożenie... ze strony krwawych elfów. Dowiedz się... co one... knują!$B$BSą na... grani za mną.', 'Zabij 10 zwiadowców krwawych elfów, a następnie wróć do Tolaana na Grani Cienia w Dolinie Ammen.', '', 'Wróć do Tolaana na Grani Cienia w Dolinie Ammen.', '', '', '', '', 0),
(10304, 'plPL', 'Obrońca Aldar', 'Dzięki twojej pomocy znaleźliśmy rozwiązanie naszych problemów szybciej, niż śmiałam mieć nadzieję.$b$bNie mam już dla ciebie innej pracy. Z resztą poradzę sobie razem z moimi uczniami.$b$b$GPowinieneś:Powinnaś; porozmawiać z Obrońcą Aldarem po drugiej stronie statku.', 'Porozmawiaj z Obrońcą Aldarem na Miejscu Katastrofy w Dolinie Ammen.', '', '', '', '', '', '', 0),
(10324, 'plPL', 'Wielkie łowy na księżycowe jelenie', 'Dobra robota, $N! Dobra robota!$b$bSkoro już $gzaprawiłeś:zaprawiłaś; się w łowach na księżycowe jelenie, czas przejść do groźniejszej zwierzyny. Nie daj się zwieść obojętności księżycowych rogaczy: rozdrażnione są groźnymi przeciwnikami.$b$bRogacze znajdziesz na północ stąd. Udanych łowów.', 'Przynieś 6 skór księżycowych rogaczy Acteonowi w Lazurowej Strażnicy.', '', 'Wróć do Acteona w Lazurowej Strażnicy na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(10350, 'plPL', 'Behomat', 'Przez czas, który spędziliśmy razem, nauczyłam cię wielu twardych lekcji, ale pora, bym powierzyła cię mądrzejszym rękom.$b$bBehomat, który szkolił mnie, gdy byłam jeszcze zielona jak trawa, zostanie twoim nowym nauczycielem. Powiedziałam mu, że będziesz go szukać, więc cię oczekuje.$b$bZnajdziesz go pośrodku Tarasu Wojowników, w najwyższym punkcie Tarasu Handlarzy w Exodarze.', 'Porozmawiaj z Behomatem na Tarasie Handlarzy w Exodarze.', '', '', '', '', '', '', 0),
(10366, 'plPL', 'Jol', 'Ścieżka Światłości i czystości nie jest łatwa, $N. Nawet ja czasem z trudem nią podążam.$b$b$GPowinieneś:Powinnaś; odszukać moją mistrzynię, Jol, w Exodarze. To ona szkoliła mnie, gdy zaczynałam swoją drogę, i wierzę, że znajdzie w tobie nową gwiazdę wśród uczniów.$b$bJol znajdziesz w Skarbcu Świateł w Exodarze, w Sanktuarium Obrońców – sali otoczonej żywym blaskiem światła.', 'Porozmawiaj z Jol w Sanktuarium Obrońców w Exodarze.', '', '', '', '', '', '', 0),
(10428, 'plPL', 'Zaginiony rybak', 'Nasza ranna podopieczna w gorączkowych snach mówiła o rybaku, Cowlenie, który znalazł się w jakichś tarapatach na Wyspie Srebrnej Mgły, na południowym zachodzie, u wybrzeży Lazurowej Mgły.$b$bPrzy wszystkim, co się dzieje, nikt nie miał okazji tego sprawdzić, ale trochę się niepokoję. Może ty coś zdziałasz, $N?', 'Odnajdź Cowlena przy południowo-wschodnich pomostach Wyspy Srebrnej Mgły, u wybrzeży Lazurowej Mgły.', '', '', '', '', '', '', 0),
(14082, 'plPL', 'Naucz się jeździć w Exodarze', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłała Aalun.$B$BAalun można znaleźć przy wejściu do Exodaru na Wyspie Lazurowej Mgły.', 'Zanieś tę ulotkę Aalun przed Exodarem na Wyspie Lazurowej Mgły.', '', 'Wróć do Aalun na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(14169, 'plPL', 'Wdzięczni umarli', 'Dobrze znów odwiedzić przyjaciół i rodzinę, choć chyba trochę przesadziłam... Zjadłam już wszystko, co dla mnie przygotowali!$B$BCzy mogę cię prosić o jeszcze trochę tego pysznego chleba umarłych? Będę bardzo wdzięczna...$B$BPrzepis sprzedaje chyba tamten Chapman.', 'Zdobądź chleb umarłych i daj go radosnemu duchowi draenei na cmentarzu w Exodarze.$B$BUżyj pomarańczowej aksamitki, aby zobaczyć niewidzialnego na co dzień ducha.', '', 'Wróć do radosnego ducha draenei na Wyspie Lazurowej Mgły.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9279, 'plPL', '$N, na moją wieczną duszę, jak dobrze cię widzieć! Nie wiem, dlaczego Exodar się rozbił. Ocaleli tylko ci z nas, którzy byli w tej części statku.$B$BZostało niewiele czasu, jeśli mamy uratować wszystkich, których się da!', 0),
(9280, 'plPL', 'Szkoda, że te stworzenia musiały zginąć, abyśmy mogli żyć – bezmyślne zabijanie nie leży w naturze draenei. Jednak krew, którą $gzebrałeś:zebrałaś;, odnowi nasze kryształy lecznicze, więc ich śmierć nie pójdzie na marne.', 0),
(9283, 'plPL', 'Chwała Światłości! $GDokonałeś:Dokonałaś; tego, czego dokonać $gmógł tylko prawdziwy bohater:mogła tylko prawdziwa bohaterka;, $N! Draenei, któremu $guratowałeś:uratowałaś; życie, zawdzięcza je twojej ofiarności!$B$BProszę, weź tę sakwę z zapasami. Wygląda na to, że przyda ci się bardziej niż mnie.', 0),
(9287, 'plPL', 'Raduje mnie, że z własnej woli $gprzyszedłeś:przyszłaś; ze mną porozmawiać. Niegdyś odpowiadałem za szkolenie młodych paladynów wstępujących do naszego zakonu. To obowiązek i przywilej, który z pokorą podejmuję na nowo. Wspominano mi o tobie jako o kimś, kto pragnie czynić dobro w imię Światłości. Będzie dla mnie zaszczytem poprowadzić cię przez twoje pierwsze kroki jako $c.$B$BCzy zaczynamy?', 0),
(9288, 'plPL', 'Cieszę się, że do mnie $gprzyszedłeś:przyszłaś;. Od dłuższego czasu odpowiadam za szkolenie naszych młodych łowców i zamierzam pełnić tę powinność także w tym nowym świecie. Od pewnego czasu mam cię na oku i będzie dla mnie zaszczytem pomóc ci zgłębić sztukę łowów.$BCzy zaczynamy?', 0),
(9289, 'plPL', 'Dobrze, że szukasz moich wskazówek. Od stuleci uczę młodych draenejskich wojowników, więc wiem co nieco o tym, od czego należy zacząć. Widzę w tobie zadatki na $gwielkiego wojownika:wielką wojowniczkę;, ale tylko jeśli będziesz uważnie słuchać tego, czego mam cię nauczyć.$B$BCzy jesteś $ggotów:gotowa; do nauki, $N?', 0),
(9290, 'plPL', 'Cieszę się, że $gprzyszedłeś:przyszłaś; szukać mojej wiedzy. Czeka nas wiele pracy, jeśli twoje magiczne umiejętności mają zostać oszlifowane. Od ponad stu lat nauczam magii tajemnej, magii mrozu i ognia, a w tym świecie czuję je równie mocno. Czy chcesz, bym przekazała ci część tego, co wiem?', 0),
(9291, 'plPL', 'Daje mi to wielką nadzieję na przyszłość, że $gprzyszedłeś:przyszłaś; szukać mojej mądrości. Choć mam tu pełne ręce roboty z naszymi rannymi, nie jestem aż tak zajęty, by nie znaleźć chwili i nie pomóc ci w pierwszych krokach jako $c. Kroczyć w Światłości to najwyższe z powołań i jestem pewien, że jesteś więcej niż $ggotów:gotowa; je podjąć! Porozmawiaj ze mną ponownie, gdy poczujesz, że możesz zacząć szkolenie.', 0),
(9293, 'plPL', 'Te się nadadzą. Dziękuję, $N!$B$BPod twoją nieobecność udało mi się zebrać trochę sprzętu do analizy próbek. To powinno zająć tylko chwilę.', 0),
(9294, 'plPL', 'Z tego, co opisujesz, środek neutralizujący zadziałał! Szkoda tylko, że nie wiem, jak długo to potrwa; naprawdę musimy całkiem usunąć ten kryształ energii z jeziora.$B$BDziękuję ci, $N! Od razu powiem Tedonowi, żeby wypróbował środek neutralizujący na jednym ze schwytanych zwierząt.', 0),
(9303, 'plPL', 'Skoro wiele lunozwierzy jest już zaszczepionych, możemy się skupić na wydostaniu się stąd i nie martwić się, że wytępimy całą miejscową populację lunozwierzy.$B$BProszę, wybierz coś spośród tych rzeczy. $GSpisałeś:Spisałaś; się i zasługujesz na nagrodę!', 0),
(9305, 'plPL', 'Pokaż mi je.$B$BTak, myślę, że świetnie się nadadzą; dobra robota, $N. Emiter jest dość skomplikowany, więc naprawa może chwilę potrwać. Dam ci znać, gdy będzie gotowy.$b$bTymczasem możesz sprawdzić, czy Obrońca Aldar nie ma dla ciebie jakiegoś zadania.', 0),
(9309, 'plPL', 'Pomocy... krwawe elfy! Zasadzka... na mnie. Niewiele... mi zostało.', 0),
(9311, 'plPL', 'Dziękuję, że $gzająłeś:zajęłaś; się geodetką krwawych elfów. Z pewnością to ona im przewodziła. Bądź $gspokojny:spokojna;, rozprawimy się z resztkami ich oddziału, jeśli jeszcze kręcą się w pobliżu.$B$BProszę, weź jedną z tych broni w dowód mojej wdzięczności.', 0),
(9312, 'plPL', 'Mam, mam! Chyba udało mi się naprawić emiter! Zaraz, tylko uruchomię ten ostatni kryształ i powinno działać.$B$BSpójrz na emiter, $N. Wygląda na to, że zaczyna działać... ktoś się pojawia!', 0),
(9313, 'plPL', 'Ach, dobrze cię znowu widzieć! Cieszę się, że obu nam udało się naprawić emitery, bo inaczej moglibyśmy się nigdy nie odnaleźć. I nie martw się, dopilnujemy, żeby Dolina Ammen dostała pomoc i zapasy.$B$BSkoro mowa o pomocy, teraz, gdy już tu jesteś, obejdź okolicę i przedstaw się pozostałym. Wiem, że jest mnóstwo do zrobienia.', 0),
(9314, 'plPL', 'Och, musisz być $gjednym:jedną; z ocalałych, o których słyszeliśmy!$b$bCieszę się, że $gprzyszedłeś:przyszłaś;. Nie martw się, wyślemy kogoś, kto zajmie się ranną nogą Aeuna.$B$BBardzo chętnie wysłucham całej twojej dramatycznej opowieści o ocaleniu. Musisz być bardzo $godważny:odważna;, skoro $gdotarłeś:dotarłaś; aż tutaj.', 0),
(9369, 'plPL', 'Szkoda, że te stworzenia musiały zginąć, abyśmy mogli żyć – bezmyślne zabijanie nie leży w naturze draenei. Jednak krew, którą $gzebrałeś:zebrałaś;, odnowi nasze kryształy lecznicze, więc ich śmierć nie pójdzie na marne.', 0),
(9371, 'plPL', 'Och, dzięki niebiosom, że jesteś. Mamy wiele do zrobienia.', 0),
(9409, 'plPL', 'Dobra robota! To świetnie się nada do odnowienia naszych wyczerpanych kryształów leczniczych.$B$BAle skoro już tu jesteś, mam dla ciebie jeszcze jedno zadanie, jeśli zechcesz się go podjąć.', 0),
(9421, 'plPL', 'Jestem Firmanvaar i mądrze $gpostąpiłeś:postąpiłaś;, szukając mnie. Moim powołaniem jest nauczanie szamanów, zwłaszcza tych, którzy dopiero zaczynają naukę.$B$BSzamanizm jest wśród draenei dopiero odkrywany na nowo, $N. $GOdważny jesteś:Odważna jesteś;, że podążasz tą ścieżką, bo nie cieszy się ona popularnością wśród twoich pobratymców.$B$BBędę tutaj, gdy poczujesz, że możesz podjąć dalsze szkolenie.', 0),
(9449, 'plPL', 'Śmiało sobie poczynasz, szukając mojej mądrości po tym, co twój lud uczynił tym wyspom, $gprzybyszu:przybyszko;! Mimo to twoja odwaga wiele znaczy, więc przekażę ci nieco wiedzy.$B$BZiemia pod twoimi stopami jest fundamentem wszystkiego. Niebo, wody, nawet potężny ogień – wszystko spoczywa na jej barkach. Podczas gdy tamte często rozpętują chaotyczne nawałnice, ziemia trwa. Daje siłę i hart samemu rdzeniowi twojej istoty.$B$BTeraz dowiedziesz swej wartości, szamanie.', 0),
(9450, 'plPL', 'Dobrze się $gspisałeś:spisałaś;. Przerzedzając niespokojne duchy, $gpomogłeś:pomogłaś; uleczyć zachwianie równowagi między żywiołami, które twój lud nieumyślnie spowodował.$B$BPrzez całą swoją drogę szamana musisz o tym pamiętać, gdy będziesz przywoływać naszą moc. Równowaga musi zostać zachowana.', 0),
(9451, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Pomagając przywrócić równowagę żywiołów w gaju, $gstworzyłeś:stworzyłaś; również równowagę między żywiołem ziemi tego świata a draenei. Może to pomoże zyskać zrozumienie tych spośród nas, którzy nie pochwalają naszych ścieżek?$B$BStworzę dla ciebie totem, przez który będziesz $gmógł:mogła; przyzywać moc ziemi, by spełniała twoją wolę. A z czasem odsłonią się przed tobą kolejne tajemnice ziemi.$B$BA teraz weź swój totem, szamanie.', 0),
(9452, 'plPL', 'Mam nadzieję, że murloki nie sprawiły ci zbyt wielu kłopotów, $N. Jestem ci winna ogromną wdzięczność za wszystko, co $gzrobiłeś:zrobiłaś;.$B$BMoże nauczę cię łowić ryby? Dam ci nawet wędkę i błystkę.', 0),
(9453, 'plPL', 'Biedna Diktynna... Ten murlok nieźle ją wystraszył.$B$B<Acteon wzdycha.>$B$BMiejmy nadzieję, że wkrótce wyliże się z ran...$B$BA więc, jak mniemam, szukasz pracy. Cóż, w Lazurowej Strażnicy znajdzie się jej pod dostatkiem!', 0),
(9454, 'plPL', 'Brawo, $N, brawo!$b$bProszę, pod twoją nieobecność upiekłem trochę polędwicy. Może chcesz też przepis?', 0),
(9455, 'plPL', 'Jak coś takiego trafiło do żołądka nocnego tropiciela? Czy szczątki z katastrofy mogły skazić więcej zwierząt?', 0),
(9456, 'plPL', 'Oby tylko nie było za późno...', 0),
(9461, 'plPL', 'Witaj, $N, spodziewałem się ciebie. Mam nadzieję, że dobrze się dziś miewasz?', 0),
(9463, 'plPL', 'Miejmy nadzieję, że ta maść wzmocni jej ducha!', 0),
(9464, 'plPL', 'Ufam, że płomień, który widzę w twoich oczach, bierze się z pragnienia, by wzrastać i rozumieć? Dobrze!$B$BTuluun przysłał cię tutaj, bo widzi w tobie zdolność zarówno do nauki, jak i do pomocy w rozwiązaniu problemu, który wywołała katastrofa waszego Exodaru.$B$BZobaczymy.', 0),
(9465, 'plPL', 'Widzisz, że jej ogień nigdy nie gaśnie? To dzieło Hauteura. Symbol jego pychy. Płomień ma strawić to, co pali, a potem sam zgasnąć, by w innym czasie odrodzić się na nowo.$B$BPomógłbym ci zgasić pochodnię, ale musi płonąć, byś $gmógł:mogła; rozprawić się z Hauteurem. Niech jeszcze chwilę popłonie.', 0),
(9467, 'plPL', 'Lekcja, którą dziś tu otrzymujesz, jest cenna. To opowieść o końcach i nowych początkach.$B$BGdy rozmawialiśmy po raz pierwszy, mówiłem ci, że ogień to nie tylko zniszczenie, ale i odnawiająca siła żywiołów. Swoimi czynami $gzarówno zniszczyłeś, jak i ocaliłeś:zarówno zniszczyłaś, jak i ocaliłaś; Hauteura, bo odrodzi się on ze swoich prochów.', 0),
(9468, 'plPL', '$GPrzeszedłeś:Przeszłaś; przez oczyszczający ogień zniszczenia i $godrodziłeś się:odrodziłaś się;, $N. To podobne do udręki, przez którą przechodzi teraz lud draenei. A ratując Hauteura przed nim samym, $gumocniłeś:umocniłaś; swoją więź z żywiołem ognia tego świata.', 0),
(9473, 'plPL', 'Patrz, jak roślina czyni swoje czary.', 0),
(9505, 'plPL', 'Mówisz, że $gznalazłeś:znalazłaś; kogoś z naszej załogi i że jest ranna? Natychmiast wyślę jednego z moich marynarzy do waszej wioski!', 0),
(9506, 'plPL', 'Ale z ciebie zaradna osoba! Dzięki naszemu sprzętowi nawigacyjnemu ustalimy, jak bardzo zboczyliśmy z kursu.$b$bAle zaraz, co to? W mapę jest coś zawinięte. Niech no zobaczę...$b$bTo rozkazy od magnata Razdunka ze spółki Gitgeszeft. Według tych planów przybyli tu, by ogołocić wyspę z kryształowych szczątków, a gdy skończą, porwać nasze okręty.$b$bNa krzaczaste brwi Miedziobrodego! To dlatego zmusili nas do lądowania? Skąd mogli znać nasze plany?$b$bCzuję tu zdrajcę...', 0),
(9512, 'plPL', 'Złote z ciebie serce, $gprzybyszu:przybyszko;. To porządnie podniesie morale załogi.\n', 0),
(9513, 'plPL', 'Chwała Elunie! Niespokojne duchy mogą jednak zaznać ukojenia.', 0),
(9514, 'plPL', 'Nie umiem odczytać tych run, ale znam kogoś, kto umie...', 0),
(9515, 'plPL', 'Skoro watażka Sriss\'tiz nie żyje, groźba inwazji nag jest już tylko odległym wspomnieniem. Na razie jesteśmy bezpieczni...$B$BMuszę przyznać, że źle o tobie myślałam, $N. $GPokazałeś:Pokazałaś;, że nie masz nic wspólnego z plugastwem, jakim był Archimond. Przyjmij to jako dar od nocnych elfów.', 0),
(9523, 'plPL', 'Mój tatko byłby dumny! Jego chłopak trafia na żyłę złota w pierwszych ruinach nocnych elfów, na jakie się natknął... Oczywiście z twoją pomocą. Tak, tak, nie martw się, nie pominę cię przy tym odkryciu. Nazywasz się $N, prawda? W Żelaznej Kuźni dowiedzą się o tobie wszystkiego.\n', 0),
(9527, 'plPL', 'Dziękuję, $N. Ich duchy zaznają teraz spokoju.', 0),
(9528, 'plPL', '<Po twarzy Cowlena spływają łzy radości.>$B$BJak mogę ci się kiedykolwiek za to odwdzięczyć, $N? Proszę, przyjmij tę pamiątkę rodową. Wśród nocnych elfów symbolizuje świętą więź przyjaźni, zaufania i miłości. Jesteś dla mnie $Gbratem:siostrą; – od dziś aż po kres czasu...', 0),
(9530, 'plPL', 'Muszę cię ostrzec: to, o co poproszę cię teraz, będzie niebezpieczne. Nie będę o tobie gorzej myślał, jeśli postanowisz mi nie pomagać, $N.', 0),
(9531, 'plPL', 'Nie mogę w to uwierzyć! Przez cały czas to był ten gnom... Powinienem był się domyślić!', 0),
(9537, 'plPL', 'Niewiarygodne! To wszystko było częścią ich misternego planu!$B$BTe informacje muszą dotrzeć do króla i do twoich przywódców. Konsekwencje są porażające.', 0),
(9538, 'plPL', 'Totem pokrywają pierwotne znaki. Na jego powierzchni widzisz wyryte sowy, niedźwiedzie, wilki i jelenie.$B$BDostrzegasz dziwne zestawienie symboli, pod wpływem którego twoje usta same układają się w słowo A-K-I-D-A.', 0),
(9539, 'plPL', 'Totem pokrywają pierwotne znaki. Na powierzchni totemu widzisz wyryte sowy, niedźwiedzie, wilki i jelenie.$B$BDostrzegasz dziwne zestawienie symboli, pod wpływem którego twoje usta same układają się w słowo C-O-O.', 0),
(9540, 'plPL', 'Totem pokrywają pierwotne znaki. Na powierzchni totemu widzisz wyryte sowy, niedźwiedzie, wilki i jelenie.$B$BDostrzegasz dziwne zestawienie symboli, pod wpływem którego twoje usta same układają się w słowo T-I-K-T-I.', 0),
(9541, 'plPL', 'Totem pokrywają pierwotne znaki. Na powierzchni totemu widzisz wyryte sowy, niedźwiedzie, wilki i jelenie.$B$BDostrzegasz dziwne zestawienie symboli, pod wpływem którego twoje usta same układają się w słowo Y-O-R.', 0),
(9542, 'plPL', 'Gdy odczytujesz totem, twoje usta układają się w słowo V-A-R-K. Rozumiesz, że oznacza ono sprawiedliwość.', 0),
(9544, 'plPL', '[Furbolgijski] Proroctwo mówiło o kimś, kto powstanie i wyzwoli nas z ucisku Szczecinołapych – o tym, że same duchy zwiastują przybycie tego bohatera.$B$BI oto $gprzybyłeś:przybyłaś;.$B$BKorzę się przed tobą, $gwielki:wielka;.', 0),
(9559, 'plPL', 'Przez stulecia żyliśmy we względnym pokoju ze stworzeniami tej krainy. Kilka miesięcy temu Kurz zaczął widzieć mroczne znaki. Pokój, którym tak długo się cieszyliśmy, miał przeminąć. Nie dało się przewidzieć rozmiarów katastrofy!$B$BTak oto bogowie mieli roztrzaskać naszą ziemię i zwrócić przeciw nam zarówno przyjaciół, jak i wrogów. Ale było coś jeszcze... Pośród chaosu miał powstać bohater: bohater nie z krwi Cichej Sosny. Obiecany miał wybawić nas od zagłady.$B$BTym przepowiedzianym bohaterem jesteś ty.', 0),
(9560, 'plPL', 'Nie dość, że proroctwo jest prawdziwe, to jeszcze ten pancerz jest niesamowity! To z pewnością pancerz godny czempiona! I sprzedam ci go po obniżonej cenie, $gmój bezfutry przyjacielu:moja bezfutra przyjaciółko;.$B$BŻartuję... Pierwsza część jest gratis.', 0),
(9562, 'plPL', 'Mmmm... Pyszne ziarno... Parkat będzie zachwycony!', 0),
(9564, 'plPL', '<Gurf spluwa na kępkę futra i próbuje przykleić ją do łysego placka na swoim zadku.>$B$BNa razie musi wystarczyć! Może któryś z szamanów zdoła naprawić szkody.', 0),
(9565, 'plPL', 'Krwawy kryształ roztacza chorobliwą aurę, która przenika do wody w jaskini.', 0),
(9566, 'plPL', 'Te krwawe kryształy, które $gwidziałeś:widziałaś; – moi zwiadowcy widzieli ich znacznie więcej na północy.$B$BDziękuję ci za pomoc, ale teraz proszę, zostaw mnie, bym mógł naradzić się ze starszyzną. Wezwę cię, gdy porozmawiam z pozostałymi starszymi wioski.', 0),
(9570, 'plPL', '$GObiecany:Obiecana; $gwyszedł:wyszła; z walki zwycięsko!$B$BProroctwo prawie się dopełniło. A teraz co do tej skóry...', 0),
(9571, 'plPL', 'To najmocniejszy pancerz, jaki kiedykolwiek zrobiłem! Zrób z niego dobry użytek, $N.', 0),
(9573, 'plPL', 'To może być właśnie okazja, której potrzebowaliśmy! Natychmiast wysyłam oddział do ataku! Cicha Sosna dziękuje ci za twoją służbę, $N!', 0),
(9582, 'plPL', '<Ruada z powagą kiwa głową.>$B$BA zatem stało się.$B$BJesteś $ggotów:gotowa; na kolejną lekcję, $N, ale to nie ja ci jej udzielę.', 0),
(9586, 'plPL', 'Dziękuję, że $gpomogłeś:pomogłaś; Tavarze. Tak wielu z nas nie zna tych ziem i wpada w kłopoty tam, gdzie najmniej się ich spodziewa.$B$BByłbym zaszczycony, gdybyś $gzechciał:zechciała; nosić te szaty. Świadczą o tym, że należysz do obrońców Lazurowej Strażnicy i $gjesteś oddanym wyznawcą:jesteś oddaną wyznawczynią; Światłości.', 0),
(9595, 'plPL', 'Przy każdym zaklęciu musisz się hartować przeciw jego uwodzicielskiej pokusie i używać go tylko wtedy, gdy trzeba, w dobrym celu. Mam nadzieję, że upiór pozwolił ci ujrzeć, kim możesz się stać, jeśli popadniesz w beztroskę – $gbezmyślnym niewolnikiem:bezmyślną niewolnicą; magii.', 0),
(9602, 'plPL', '<Egzarcha Menelaous bierze od ciebie list i zaczyna czytać.>$B$BPrzeklęci... Niech ich wszystkich pochłonie Otchłań. Mieli szpiega, który obserwował wszystko, co robiliśmy! I to od jak dawna?$B$BNatychmiast powiadomię Velena!$B$B$GOddałeś:Oddałaś; nam wielką przysługę, $N. Bądź w pogotowiu, bo odezwę się do ciebie, gdy tylko Prorok przekaże mi wskazówki, co robić.', 0),
(9612, 'plPL', 'Dobra robota, $N. Naprawdę dobra robota! Wyrastasz na kogoś wyjątkowego – przewyższasz swoich rówieśników o głowę. Przyjmij to w nagrodę!', 0),
(9616, 'plPL', 'Na bezbrodą, geometryczną głowę O\'rosa! Dobrze, że mi to $gprzyniosłeś:przyniosłaś;, $N. Te krwawe elfy są żądne... no cóż, krwi. Natychmiast powiadomię Velena! Przyjmij to w nagrodę.', 0),
(9622, 'plPL', 'Wizje, powiadasz? Ciekawe... I to proroctwo się spełniło?$B$BAle mówisz, że widzieli rdzeń energetyczny Exodaru? I że w wizji był też O\'ros? Co to może znaczyć?', 0),
(9623, 'plPL', '<Torallius wzdycha.>$B$BNo dobrze, pokaż mi te rozkazy.', 0),
(9625, 'plPL', 'No, $gdotarłeś:dotarłaś; aż tutaj! Zagońmy cię do roboty, zanim za bardzo się pokrwawisz.', 0),
(9672, 'plPL', '$GSłyszałeś:Słyszałaś; kiedyś o krwawej klątwie, szczurze lądowy? Nie, oczywiście, że nie. To krwawa klątwa zatopiła wszystkie te statki. Tę zepsutą, zbezczeszczoną część tutejszych wód zwą Rafą Krwawej Klątwy – to miejsce na świecie, którego nigdy nie chcesz odwiedzić. Sam tkwię tu od 20 lat.$B$BSzkorbut, akurat! Zginąłem na tych dzikich brzegach jako strawa dla smoków... Ach, ale to opowieść na inny raz. Teraz musimy pomóc biednym duszom uwięzionym na tej rafie.', 0),
(9676, 'plPL', 'Raduje mnie, że z własnej woli $gprzyszedłeś:przyszłaś; ze mną porozmawiać. Niegdyś odpowiadałem za szkolenie młodych paladynów wstępujących do naszego zakonu. To obowiązek i przywilej, który z pokorą podejmuję na nowo. Wspominano mi o tobie jako o kimś, kto pragnie czynić dobro w imię Światłości. Będzie dla mnie zaszczytem poprowadzić cię przez twoje pierwsze kroki jako $c.$B$BCzy zaczynamy?', 0),
(9751, 'plPL', '$GSłyszałeś:Słyszałaś; kiedyś o krwawej klątwie, szczurze lądowy? Nie, oczywiście, że nie. To krwawa klątwa zatopiła wszystkie te statki. Tę zepsutą, zbezczeszczoną część tutejszych wód zwą Rafą Krwawej Klątwy – to miejsce na świecie, którego nigdy nie chcesz odwiedzić. Sam tkwię tu od 20 lat.$B$BSzkorbut, akurat! Zginąłem na tych dzikich brzegach jako strawa dla smoków... Ach, ale to opowieść na inny raz. Teraz musimy pomóc biednym duszom uwięzionym na tej rafie.', 0),
(9798, 'plPL', 'Pokaż, przeczytam te plany.$B$BKrwawe elfy przyszły tu za nami? Są na wskroś złe i powinny zostać zmiecione z powierzchni ziemi!$B$B<Obrońca przez chwilę odzyskuje panowanie nad sobą.>$B$BPrzepraszam, to było niestosowne. Jesteśmy twoimi dłużnikami za zdobycie tych informacji, $N.', 0),
(9799, 'plPL', 'Wyglądają na piękne okazy. Dziękuję za pracę w terenie. Gdy tylko znajdę czas, żeby je zbadać, powinnam móc powiedzieć, czego trzeba, by uzdrowić pola.', 0),
(10302, 'plPL', '$GSkończyłeś:Skończyłaś;? To dobra wiadomość. Oby w przyszłości udało nam się znaleźć sposób, by nie zabijać tych zmutowanych stworzeń.$b$bChyba opracowałam plan, który może dać nam inne rozwiązanie tego problemu, ale będę potrzebowała twojej pomocy.', 0),
(10303, 'plPL', 'Te krwawe elfy chcą nas wszystkich wymordować. Jak mamy je od tego odwieść?', 0),
(10304, 'plPL', '$N, tak? Słyszałem wiele dobrego o tobie i o tym, czego $gdokonałeś:dokonałaś; w tak krótkim czasie od przebudzenia.$B$BZ pewnością będziemy potrzebować twojej pomocy, by przywrócić tu porządek. Jestem pewien, że Zhanaa, o tam, też przyjęłaby twoją pomoc.', 0),
(10324, 'plPL', 'Wspaniale! Wyrasta z ciebie $gprawdziwy łowca:prawdziwa łowczyni;, $N.$b$b$GChciałbyś:Chciałabyś; wyglądać bardziej jak ja? Oto twoja szansa! Gdy $gpolowałeś:polowałaś;, zrobiłem te rzeczy z kilku skór rogaczy, które mi się tu poniewierały. Wybierz coś!', 0),
(10350, 'plPL', 'Ach, więc w końcu $gprzybyłeś:przybyłaś;. Jestem Behomat i nauczę cię sztuki wojownika. Ruada opowiedziała mi o twojej próbie z pustoszycielem i jestem pod wrażeniem. Mam też dla ciebie podarunek.$B$BTo, co zdołaliśmy ocalić z wraku Exodaru, jest skromne i musi trafić do najbardziej godnych. Proszę, weź broń pasującą do twojego stylu walki i noś ją ze świadomością, że na nią $gzasłużyłeś:zasłużyłaś;.$B$BA skoro mowa o stylach walki, czas, byś $gnauczył:nauczyła; się czegoś nowego.', 0),
(10366, 'plPL', '$N, spodziewałam się ciebie.$B$BTullas wychwalała cię pod niebiosa i chętnie poprowadzę dalej twoje szkolenie na ścieżce Światłości. Gdy będziesz $ggotów:gotowa; głębiej zrozumieć swoje zdolności i moc, poprowadzę cię.', 0),
(10428, 'plPL', 'Moja rodzina... Co ja zrobiłem... Co mogłem zrobić?$b$bDlaczego spotyka mnie taka kara?', 0),
(11735, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Wyspie Lazurowej Mgły!', 0),
(11806, 'plPL', 'Uczcij płomień Wyspy Lazurowej Mgły!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9280, 'plPL', '$N, czy $gzebrałeś:zebrałaś; już krew ciem potrzebną do kryształów leczniczych? Ocaleni są rozproszeni po całej dolinie, liczy się każda chwila!', 0),
(9283, 'plPL', 'Z twoją pomocą jeszcze to przetrwamy.', 0),
(9293, 'plPL', 'Potrzebuję wszystkich próbek w dobrym stanie, jeśli mamy mieć szansę na oczyszczenie jeziora.$B$BNie mamy wiele czasu, $N!', 0),
(9294, 'plPL', 'Im szybciej rozproszysz środek w jeziorze, tym mniej miejscowych stworzeń zmutuje od picia tej wody – nas samych nie wyłączając!$B$BPrzykro mi, że nie możemy nic zrobić dla biednych stworzeń, które już zostały zarażone. Gdyby tylko mój sprzęt laboratoryjny był cały...', 0),
(9303, 'plPL', 'Im więcej zdziałamy w Gniazdowym Lesie, tym szybciej Zhanaa wróci do pracy.', 0),
(9305, 'plPL', 'Gdy tylko będziemy mieć te części zapasowe, wiem, że naprawimy emiter. Przy odrobinie szczęścia znajdzie się tam jeszcze ktoś, z kim da się porozmawiać.', 0),
(9311, 'plPL', 'A więc to prawda... oddział zwiadowczy krwawych elfów tutaj, w Dolinie Ammen! Jak zdołali nas wyśledzić?$B$BNatychmiast kogoś wyślę, żeby sprowadził Tolaana.', 0),
(9369, 'plPL', 'Czy $gzebrałeś:zebrałaś; już krew ciem potrzebną do kryształów leczniczych? Ocaleni są rozproszeni po całej dolinie, liczy się każda chwila!', 0),
(9409, 'plPL', 'Witaj, $N. Co tam masz? Czy to dla mnie?', 0),
(9451, 'plPL', 'Razem Złamani i draenei na nowo zgłębią tajemnice, które kryją w sobie żywioły.$B$BCzy wracasz z tym, co jest potrzebne do stworzenia twojego totemu ziemi?', 0),
(9452, 'plPL', 'Uważaj na murloki: to dziwne i niezwykle irytujące małe stworzenia.', 0),
(9453, 'plPL', 'Co sądzisz o mojej zbroi? Sam ją wykonałem! Jest nieco inna od tego, co tradycyjnie nosimy, ale niezwykle wygodna.', 0),
(9454, 'plPL', 'Skóra jeleni jest cienka, dzięki czemu ich mięso bywa delikatne i soczyste.', 0),
(9455, 'plPL', 'Co $gznalazłeś:znalazłaś;? Gdzie?', 0),
(9456, 'plPL', 'Nie możemy ryzykować, że to skażenie się rozprzestrzeni. Wieści, które docierają do mnie z Krwawej Strażnicy, są wystarczająco złe. Trzeba to powstrzymać natychmiast!', 0),
(9463, 'plPL', 'Obawiam się, że jej stan stale się pogarsza.', 0),
(9465, 'plPL', 'Masz pochodnię?', 0),
(9467, 'plPL', 'Nie odzywaj się do mnie, dopóki nie zdobędziesz prochów Hauteura.', 0),
(9468, 'plPL', 'Wyglądasz na nieco $gprzypalonego:przypaloną; na brzegach. Jak ci poszło obcowanie z płomieniem, $N?', 0),
(9473, 'plPL', 'Nie trać czasu, $gchłopcze:dziewczyno;.', 0),
(9506, 'plPL', 'Masz szczęście, $gprzybyszu:przybyszko;?', 0),
(9512, 'plPL', 'Arrr... Jarrr... Niech mnie kule biją... Eee, wybacz, $gchłopcze:dziewczyno;, muszę ćwiczyć moją piracką gadkę, coby jej nie zapomnieć...', 0),
(9513, 'plPL', 'Czynisz dobro dla mojego ludu, $N.', 0),
(9514, 'plPL', '$GZnalazłeś:Znalazłaś; coś?', 0),
(9515, 'plPL', 'Zachowaj czujność!', 0),
(9523, 'plPL', 'Nie wracaj bez starożytnych relikwii.', 0),
(9527, 'plPL', 'Moja żona miała na imię Thalrisa, a córka – Magwin.', 0),
(9528, 'plPL', 'Witaj, $N.', 0),
(9530, 'plPL', 'Uwielbiam, kiedy plan zaczyna się składać w całość...', 0),
(9531, 'plPL', 'Ten zdrajca pożałuje, że zadarł z Dowództwem floty Przymierza!', 0),
(9537, 'plPL', '$GZnalazłeś:Znalazłaś; tego kłamliwego psa?', 0),
(9538, 'plPL', 'Słyszysz niskie buczenie dobiegające z totemu.', 0),
(9544, 'plPL', '[Furbolgijski] A więc proroctwo Akida jest prawdziwe... Zesłano nam bohatera.', 0),
(9560, 'plPL', 'Paskudne małe stworzenia. Nawet Ślepy Wartownik by je zobaczył... a przecież jest ślepy.', 0),
(9562, 'plPL', 'Murlok kopnął mnie w tyłek i na mnie napluł... w biały dzień!', 0),
(9564, 'plPL', 'Czy to jest to, co myślę?', 0),
(9570, 'plPL', '<Kurz chrząka na ciebie.>', 0),
(9571, 'plPL', 'Witaj, $gbohaterze:bohaterko;!', 0),
(9573, 'plPL', 'Czy zadanie zostało wykonane?', 0),
(9582, 'plPL', '$GDobiłeś:Dobiłaś; tę bestię?', 0),
(9586, 'plPL', '$GOdnalazłeś:Odnalazłaś; Tavarę?', 0),
(9595, 'plPL', '$GStawiłeś:Stawiłaś; czoła swoim koszmarom?', 0),
(9602, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(9616, 'plPL', 'Tak? Jestem bardzo zajęty, $N.', 0),
(9623, 'plPL', '<Torallius poprawia przepaskę na oku, żeby ci się przyjrzeć.>$B$BTo najlepsze, co możemy dać Ręce Argusa?', 0),
(9718, 'plPL', 'Witaj, $N.', 0),
(9798, 'plPL', 'Co tam masz?', 0),
(9799, 'plPL', 'Witaj, $N. Masz już te kwiaty?', 0),
(10302, 'plPL', 'Pracuję nad rozwiązaniem, które moim zdaniem może się sprawdzić przy tych dziwnych stworzeniach. Potrzebuję tylko więcej czasu.', 0),
(10303, 'plPL', 'Jest ich za dużo... Musimy przerzedzić ich szeregi, bo inaczej ocaleni nie będą mieli z nimi żadnych szans.', 0),
(10324, 'plPL', 'Skóry rogaczy są grube i wytrzymałe, a ich mięso bardzo twarde – prawie niejadalne, ale skóry możemy wykorzystać do innych celów.', 0),
(10621, 'plPL', 'Co tam masz?', 0),
(10623, 'plPL', 'Co tam masz?', 0),
(10769, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(10776, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(11530, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(11632, 'plPL', 'Co tam masz?', 0),
(12019, 'plPL', 'Witaj, $N.', 0),
(12041, 'plPL', 'Co tam masz?', 0),
(12482, 'plPL', 'Witaj, $N.', 0),
(13349, 'plPL', 'Witaj, $N.', 0);
