INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2919, 'plPL', 'Sługo,$B$BStracono owoc kilku lat planowania. Draenei i ich żałosny przywódca znów wymknęli się Mistrzowi z rąk! Co gorsza, ukradli MÓJ statek i rozbili go na Azeroth!$B$BPrawdą jest, że eredarska agentka Mistrza zawiodła, zdołała jednak przekazać nam położenie Exodaru. Na szczęście jej tożsamość wciąż pozostaje dla draenei tajemnicą. Może jeszcze zdołamy wykorzystać ją do naszych celów.$B', 0),
(2920, 'plPL', 'Skontaktuj się z naszym szpiegiem i przygotuj zmasowany atak na draenei. Zabij ich wszystkich i odzyskaj mój statek. Tylko ciebie mam na Azeroth – tylko ty zdołasz naprawić szkody, które te bydlaki wyrządziły Exodarowi.$B$BNie zawiedź mnie, gnomie. Jeśli twoja żądza bogactwa przeszkodzi w wykonaniu moich rozkazów, spędzisz wieczność na modlitwie. Będziesz się modlić o śmierć, która uwolni cię od tortur, jakie rozpętam, jeśli się zawahasz.$B$B– Król Słońcobieżca$B', 0);
