(4912, 'plPL', '%s się śmieje.', '', 0),
(7382, 'plPL', '%s się śmieje.', '', 0),
(9359, 'plPL', 'GIŃ!', 'GIŃ!', 0),
(10645, 'plPL', '%s wpada w szał!', '', 0),
(12446, 'plPL', '', 'Mamy wielkie szczęście, że żyjemy – ty i ja!', 0),
(12451, 'plPL', '$N, $gocaliłeś:ocaliłaś; mnie! Mam wobec ciebie dług, którego nigdy nie zdołam spłacić. Pójdę sprawdzić, czy mogę pomóc innym.', '$N, $gocaliłeś:ocaliłaś; mnie! Mam wobec ciebie dług, którego nigdy nie zdołam spłacić. Pójdę sprawdzić, czy mogę pomóc innym.', 0),
(12514, 'plPL', '%s z wdzięcznością kiwa głową.', '', 0),
(12516, 'plPL', '%s wydaje się uradowany.', '', 0),
(12517, 'plPL', '%s wygląda na zdezorientowanego.', '', 0),
(12518, 'plPL', '%s wydaje się oszołomiony.', '', 0),
(12520, 'plPL', '%s nie wygląda, jakby przeszkadzało mu działanie kryształu.', '', 0),
(12521, 'plPL', '%s nie spodobało się to, co właśnie zaszło.', '', 0),
(12525, 'plPL', 'Wiele jest ścieżek Światłości, $N. Musisz zdecydować, którą z nich podążysz w tym świecie – czy w jakimkolwiek innym.', '', 0),
(12767, 'plPL', '', 'Nie weźmiecie mnie żywcem, szumowiny!', 0),
(12769, 'plPL', 'Czego bym teraz nie dał za kryształ leczniczy!', '', 0),
(12771, 'plPL', '', 'Jak my się stąd kiedykolwiek wydostaniemy?', 0),
(12773, 'plPL', '', 'Nikt nie podda w wątpliwość twoich czynów, $N. $GZrobiłeś:Zrobiłaś; to, co było konieczne.', 0),
(12774, 'plPL', 'Dobrze widzieć cię całego i zdrowego, $N!', '', 0),
(12775, 'plPL', 'Jeszcze raz dziękuję za odnowienie naszych kryształów leczniczych. Słyszę, że pomagasz wszędzie, gdzie się da. Tak trzymaj!', '', 0),
(12794, 'plPL', 'Nie... martw się... o mnie...', '', 0),
(12846, 'plPL', '', 'To wspaniała wiadomość! Twoje starania naprawdę nas ocaliły, $N!', 0),
(13113, 'plPL', 'O nie! Tracę go!', '', 0),
(13391, 'plPL', 'Choć nie mogę cię szkolić, $N, mogę ci dać moje błogosławieństwo. Krocz śmiało w Światłości!$B$BCzy coś jeszcze?', 'Choć nie mogę cię szkolić, $N, mogę ci dać moje błogosławieństwo. Krocz śmiało w Światłości!$B$BCzy coś jeszcze?', 0),
(13402, 'plPL', '', 'Ten emiter doprowadza mnie do szału! Brakuje mi całej masy części, których potrzebuję, żeby go naprawić.', 0),
(13403, 'plPL', '', '$N! Jeszcze raz dzięki za całą pomoc.', 0),
(13404, 'plPL', '', 'Nie, jeszcze nie skończyłam tych napraw. Ale to nie powinno długo potrwać.', 0),
(13408, 'plPL', 'Ostatnie, co pamiętam, to spadający statek i to, jak wsiadaliśmy do kapsuł. Pójdę zobaczyć, jak mogę pomóc. Dziękuję!', 'Ostatnie, co pamiętam, to spadający statek i to, jak wsiadaliśmy do kapsuł. Pójdę zobaczyć, jak mogę pomóc. Dziękuję!', 0),
(13409, 'plPL', 'Gdzie jestem? Kim jesteś? O nie! Co się stało ze statkiem?', 'Gdzie jestem? Kim jesteś? O nie! Co się stało ze statkiem?', 0),
(13410, 'plPL', 'Uch... co to za miejsce? Czy to tam to wszystko, co zostało ze statku?', 'Uch... co to za miejsce? Czy to tam to wszystko, co zostało ze statku?', 0),
(13411, 'plPL', 'Uuuch... Boli. Możesz mi pomóc?', 'Uuuch... Boli. Możesz mi pomóc?', 0),
(13413, 'plPL', '<Szlocha> Nienawidzę cmentarzy. Tylu zmarłych. I moja słodka Luhanaa...', '', 0),
(13414, 'plPL', '%s cicho płacze.', '', 0),
(13415, 'plPL', '%s w milczeniu wpatruje się w nagrobek przed sobą.', '', 0),
(13416, 'plPL', '%s wybucha głośnym, rozdzierającym szlochem.', '', 0),
(13417, 'plPL', '%s spuszcza głowę i wzdycha, wyraźnie wyczerpany.', '', 0),
(13418, 'plPL', 'Dlaczego, Luhanaa? Dlaczego?!', '', 0),
(13419, 'plPL', 'To ja powinienem był zginąć!', '', 0),
(13420, 'plPL', 'Nigdy cię nie zapomnę, ukochana.', '', 0),
(13421, 'plPL', 'Nigdy nie powinniśmy byli tu lecieć.', '', 0),
(13422, 'plPL', 'Tak bardzo mi ciebie brakuje!', '', 0),
(13423, 'plPL', 'Jeśli kiedyś znajdę winnych tej katastrofy...!', '', 0),
(13424, 'plPL', 'Zawsze będziesz tu, ze mną.', '', 0),
(13425, 'plPL', 'Spoczywaj w pokoju, moja słodka, najsłodsza Luhanaa.', '', 0),
(13426, 'plPL', 'Nie pozwolimy wam opuścić tej doliny!', 'Nie pozwolimy wam opuścić tej doliny!', 0),
(13427, 'plPL', 'Szkoda, że $gprzeżyłeś:przeżyłaś; katastrofę tylko po to, by zginąć tutaj.', 'Szkoda, że $gprzeżyłeś:przeżyłaś; katastrofę tylko po to, by zginąć tutaj.', 0),
(13428, 'plPL', 'Mam nadzieję, że $gpogodziłeś:pogodziłaś; się już ze światem.', 'Mam nadzieję, że $gpogodziłeś:pogodziłaś; się już ze światem.', 0),
(13429, 'plPL', 'Nikt z was nie opuści tej doliny żywy.', 'Nikt z was nie opuści tej doliny żywy.', 0),
(13440, 'plPL', 'Och, jak boli...', 'Och, jak boli...', 0),
(13441, 'plPL', 'Wszystko mnie boli. Proszę, niech to się skończy...', 'Wszystko mnie boli. Proszę, niech to się skończy...', 0),
(13442, 'plPL', 'Nie wiem, czy dam radę. Proszę, pomóż mi...', 'Nie wiem, czy dam radę. Proszę, pomóż mi...', 0),
(13471, 'plPL', '', 'Chwytaj sieć, $N. Nasz lud potrzebuje pożywienia!', 0),
(13473, 'plPL', 'Proszę, naucz mnie łowić ryby, Diktynno.', 'Proszę, naucz mnie łowić ryby, Diktynno.', 0),
(13474, 'plPL', 'Chcę obejrzeć twoje towary, Diktynno.', 'Chcę obejrzeć twoje towary, Diktynno.', 0),
(13496, 'plPL', 'Spójrz na Exodar, $gmój młody przyjacielu:moja młoda przyjaciółko;. Trudno sobie wyobrazić, że przetrwaliśmy taką katastrofę.$B$B<Menelaous wzdycha.>$B$BProrok mówi, że to tutaj w końcu rozstrzygną się nasze losy. Dziesięć żywotów spędzonych na ucieczce przed szaleństwem Płonącego Legionu... tu wreszcie stawimy opór.$B$BKoniec z ucieczką... Jestem gotów umrzeć.', '', 0),
(13546, 'plPL', '', 'Nie mam już dla ciebie pracy, $N. Chcę jednak, żebyś $gwiedział:wiedziała;, że te lucjany czerwone, które razem łowiliśmy, były czymś wyjątkowym, czego nigdy nie zapomnę...', 0),
(13549, 'plPL', 'Wróć do swojego ludu i powiedz im, żeby przysłali do mnie jednego ze swoich szamanów.', '', 0),
(13550, 'plPL', 'Wróć do draenei i powiedz im, żeby przysłali do mnie jednego ze swoich szamanów.', '', 0),
(13551, 'plPL', 'Twoja praca tutaj dobiegła końca, $gszamanie:szamanko;. Wróć do swojego ludu.', '', 0),
(13552, 'plPL', 'Czy masz dość zrozumienia, by iść dalej, $gszamanie:szamanko;? Czy wiesz, dlaczego tu jesteś?', '', 0),
(13557, 'plPL', 'Twoja obecność tutaj może oznaczać tylko kłopoty, $gsynu:córko; Hordy. Idź w pokoju.', '', 0),
(13558, 'plPL', 'Rozejrzyj się, $gszamanie:szamanko;. Czy dostrzegasz równowagę żywiołów w ziemi, powietrzu, wodzie i ogniu, który dotknął ich wszystkich?', '', 0),
(13565, 'plPL', '', 'Jeśli jeszcze nie umiesz korzystać z bandaży, chętnie pokażę ci podstawy ich przygotowywania i zakładania. Właściwe opatrzenie ran często decyduje o życiu lub śmierci.', 0),
(13566, 'plPL', 'Chcę się nauczyć wszystkiego, czego możesz mnie nauczyć o pierwszej pomocy, Fateemo.', 'Chcę się nauczyć wszystkiego, czego możesz mnie nauczyć o pierwszej pomocy, Fateemo.', 0),
(13568, 'plPL', 'Mam teraz mnóstwo pracy, $N. Proszę, wybacz mi.', 'Mam teraz mnóstwo pracy, $N. Proszę, wybacz mi.', 0),
(13572, 'plPL', 'Tak być nie może! Musimy zabezpieczyć fundamenty, bo inaczej cała konstrukcja się zawali!', '', 0),
(13576, 'plPL', 'Na plugawy cyc przegniłego torsu Kil\'jaedena, cały tył jest rozwalony! Jak ktokolwiek ma tu mieszkać? Dość się napatrzyłem!', '', 0),
(13577, 'plPL', 'Witaj, $N. Przysłano mnie tu z Exodaru, bym nadzorował budowę Lazurowej Strażnicy.', '', 0),
(13578, 'plPL', 'Chcę się nauczyć inżynierii, Daelo.', 'Chcę się nauczyć inżynierii, Daelo.', 0),
(13579, 'plPL', 'Chcę obejrzeć twoje towary, Daelo.', 'Chcę obejrzeć twoje towary, Daelo.', 0),
(13580, 'plPL', 'Mam mnóstwo roboty! Czemu nie dadzą mi spokojnie pracować?', '', 0),
(13592, 'plPL', 'Alchemik potrafi czynić cuda ze zwykłymi ziołami, przemieniając je w trwałe mikstury o najróżniejszym działaniu – od leczenia po oddychanie pod wodą i wszystko pomiędzy.', '', 0),
(13593, 'plPL', 'Chcę się szkolić na alchemika, Daedalu.', 'Chcę się szkolić na alchemika, Daedalu.', 0),
(13596, 'plPL', '', 'Teraz nałożę maść na jej rany.', 0),
(13597, 'plPL', '', 'Wygląda na to, że maść nie działa. Jaka szkoda...', 0),
(13598, 'plPL', 'Może jest jeszcze jakieś wyjście. Podejdź tu, $N. Wyjaśnię ci, czego potrzebuję.', '', 0),
(13599, 'plPL', 'To powinno wystarczyć...', '', 0),
(13600, 'plPL', 'Obudź się, maleńka. Zbudź się ze snu... Jesteś już bezpieczna.', '', 0),
(13602, 'plPL', '', '%s siada.', 0),
(13603, 'plPL', '', 'Gdz... Gdzie ja jestem? Co... Co to za miejsce?', 0),
(13604, 'plPL', '', 'NA ŚWIATŁO ELUNY! Eredarowie! Przeklęte demony, co mi zrobiliście? Nie przybyłam sama, będziemy z wami walczyć, jak walczyliśmy w przeszłości! Ja...', 0),
(13605, 'plPL', '', '%s znów zapada w śpiączkę.', 0),
(13608, 'plPL', '', 'Man\'ari... Ale jak... Nie jesteśmy eredarami! Musi się o tym dowiedzieć! Jeśli są tu inni tacy jak ona, musimy ich odnaleźć i wszystko wyjaśnić...', 0),
(13641, 'plPL', 'Ahoj, kamracie. Ciastek me imię, a gotowanie me rzemiosło. Ród McCienkisosów to długa linia kucharzy i kupców, co się trudzą, by dogodzić delikatniejszym zmysłom chłopa i baby.', '', 0),
(13642, 'plPL', 'Naucz mnie gotować, Ciastku.', 'Naucz mnie gotować, Ciastku.', 0),
(13643, 'plPL', 'Pokaż mi swoje towary, Ciastku.', 'Pokaż mi swoje towary, Ciastku.', 0),
(13644, 'plPL', '', 'Potrzebujesz czegoś?', 0),
(13645, 'plPL', 'Chcę zostać kowalem.', 'Chcę zostać kowalem.', 0),
(13646, 'plPL', 'Pokaż mi swoje towary, Calypso.', 'Pokaż mi swoje towary, Calypso.', 0),
(13686, 'plPL', '', 'Dyvuun, to ty?', 0),
(13687, 'plPL', 'Tak, Zhanaa, to ja! Twój sygnał jest słaby.', '', 0),
(13688, 'plPL', '', 'Ledwie cię słyszę... <trzaski> ...budzą się!', 0),
(13692, 'plPL', 'Zhanaa! Ech, muszę naprawić to ustrojstwo!', '', 0),
(13693, 'plPL', 'Dziękuję ci, $gszamanie:szamanko;. Odrodziłem się i będę płonąć jaśniej niż kiedykolwiek!', '', 0),
(13694, 'plPL', '%s zerka na Porywczak, jakby niechętnie zabierał głos.', '', 0),
(13698, 'plPL', 'Hej, Ciastku! Co dziś na obiad? I nie mów, że kurczak!', '', 0),
(13699, 'plPL', 'Arr, admirale. Niech no pomyślę... Arrr... Coś mi się już klaruje.', '', 0),
(13700, 'plPL', 'Zdaje się, że będą soczyste żeberka wieprzowe polewane własnym wybornym sosem, a do tego tajny sos kapitana Sandersa – do maczania.\n', '', 0),
(13701, 'plPL', 'A na deser będzie sernik, świeżutki, prosto z Wichrogrodu, przyniesiony na anielskich skrzydłach...', '', 0),
(13702, 'plPL', 'Ojej! Naprawdę?', '', 0),
(13703, 'plPL', 'Nie. Nie naprawdę...', '', 0),
(13704, 'plPL', 'Będzie kurczak...', '', 0),
(13705, 'plPL', 'Jak ja cię nienawidzę, Ciastku.', '', 0),
(13706, 'plPL', '', '<Kapłanka Il\'dinare przygląda ci się podejrzliwie.>', 0),
(13707, 'plPL', '', 'Jestem nocną elfką, $gprzybyszu:przybyszko;. Choć ty możesz nic nie wiedzieć o moim ludzie, my wiemy wiele o tobie i twoich praojcach. Możesz nie nazywać siebie eredarem, ale z wyglądu macie ze sobą wiele wspólnego.$B$B$GPomogłeś:Pomogłaś; moim sojusznikom i jestem ci za to wdzięczna, ale na razie stąpasz po kruchym lodzie. Może z czasem zdołasz rozwiać wątpliwości i lęki, które noszę w sercu.', 0),
(13708, 'plPL', '', 'Witaj, $gprzybyszu:przybyszko;. Twoje szlachetne czyny zostały dostrzeżone. Niech Elune cię chroni.', 0),
(13709, 'plPL', 'Uważaj, gdzie stąpasz, $gprzybyszu:przybyszko;.', '', 0),
(13710, 'plPL', 'Do tej pory bardzo nam $gpomogłeś:pomogłaś;, $N. Dobrze zrobisz, jeśli pomożesz też innym w obozie.$B$BI nie przejmuj się tymi goblinami, wszystkim się zajmę.', '', 0),
(13711, 'plPL', '', 'Adamancie, czy mógłbyś przyjrzeć się tej tablicy i spróbować odczytać runy?', 0),
(13712, 'plPL', 'Oczywiście! Dla ciebie wszystko, skarbie!', '', 0),
(13713, 'plPL', 'No dobrze, obejrzyjmy tę tablicę.', '', 0),
(13714, 'plPL', '%s powoli czyta tablicę, bezgłośnie poruszając ustami przy słowach w ich ojczystym języku.', '', 0),
(13715, 'plPL', 'Watażka nag! O rety...', '', 0),
(13716, 'plPL', 'Cóż, nie spodoba ci się to, co mam do powiedzenia, panienko. Ta tablica to wiadomość nag. Ich przywódca, watażka Sriss\'tiz, rozkazał swoim nagom zdobyć siłą resztę wyspy.', '', 0),
(13717, 'plPL', 'I wygląda na to, że idą mu posiłki z Nazjataru!', '', 0),
(13718, 'plPL', 'Musimy coś z tym zrobić!', '', 0),
(13719, 'plPL', '', 'Dziękuję, Adamancie. Chyba wiem, kto się do tego nada.', 0),
(13729, 'plPL', 'Na co się gapisz?', '', 0),
(13730, 'plPL', 'Jestem Adamant Żelaznosercy z wielkiego miasta Żelaznej Kuźni. Jak pewnie zgadujesz po moim mundurze, należałem kiedyś do elitarnej straży Żelaznej Kuźni. Tak jest, byłem prawą ręką Magniego! Przynajmniej do czasu, aż przeszedłem w stan spoczynku. Teraz param się archeologią. To właściwie hobby, ale uznałem, że to świetny sposób, żeby zobaczyć świat!', '', 0),
(13737, 'plPL', '<Cowlen szlocha.>', '', 0),
(13738, 'plPL', 'Czym mogłem dać bogom powód, by uderzyli we mnie z taką zaciekłością? Wszystko, co kochałem, przepadło – nie żyje albo legło w gruzach. Moją rodzinę odebrały mi leśne bestie. Mój dom zrównano z ziemią. Mój statek zatonął.$B$BJestem złamanym człowiekiem, uwięzionym na złamanej wyspie.$B$BMoże $gprzybyłeś:przybyłaś; tu, by dokończyć dzieła? Zrób to szybko, nie będę się bronił. Odbierz mi życie, $gprzybyszu:przybyszko; – jestem zbyt wielkim tchórzem, by zrobić to sam. Ręka mi drży... ostrze nie trafi celnie.\n', '', 0),
(13739, 'plPL', 'Nie $gprzyszedłem:przyszłam; cię zabić, nocny elfie. I to nie bogowie to uczynili...', 'Nie $gprzyszedłem:przyszłam; cię zabić, nocny elfie. I to nie bogowie to uczynili...', 0),
(13740, 'plPL', 'Jeśli nie bogowie, to kto? Jak? Co mogło sprowadzić takie nieszczęście?', '', 0),
(13741, 'plPL', 'Obawiam się, że mój lud ponosi część winy za to zniszczenie. Jesteśmy uchodźcami, których Płonący Legion wygnał z domów. Ta tragedia to skutek naszej ostatniej ucieczki. Nasz statek się rozbił – te szczątki są jego częścią.', 'Obawiam się, że mój lud ponosi część winy za to zniszczenie. Jesteśmy uchodźcami, których Płonący Legion wygnał z domów. Ta tragedia to skutek naszej ostatniej ucieczki. Nasz statek się rozbił – te szczątki są jego częścią.', 0),
(13742, 'plPL', 'Legion? Demony? Polują na was? Mój lud także był ścigany przez Legion – ich mroczni władcy chcieli nas zatracić.$B$B<Cowlen ociera łzy.>$B$BTo dlatego przed tyloma, tyloma laty przeniosłem tu swoją rodzinę.', '', 0),
(13743, 'plPL', 'Wiele nas łączy, nocny elfie. Nie mogę oprzeć się wrażeniu, że to los nas ze sobą zetknął. Pozwól mi sobie pomóc, Cowlenie. Pozwól pomóc mojemu ludowi. Naprawimy wyrządzone krzywdy. Przysięgam.', 'Wiele nas łączy, nocny elfie. Nie mogę oprzeć się wrażeniu, że to los nas ze sobą zetknął. Pozwól mi sobie pomóc, Cowlenie. Pozwól pomóc mojemu ludowi. Naprawimy wyrządzone krzywdy. Przysięgam.', 0),
(13744, 'plPL', '', 'Nasz dom jest w tę stronę, przez gąszcz.', 0),
(13745, 'plPL', '', 'Moja biedna rodzina. Wszystko zniszczone.', 0),
(13746, 'plPL', '', 'Tato! Tato! Żyjesz!', 0),
(13747, 'plPL', '', '%s przytula ojca.', 0),
(13748, 'plPL', '', 'To $n bezpiecznie mnie tu $gprzyprowadził:przyprowadziła;, tato – podziękuj za to.', 0),
(13749, 'plPL', 'Córeczko!', '', 0),
(13770, 'plPL', '', 'Pomocy!', 0),
(13775, 'plPL', '%s podnosi flagę nag.', '', 0),
(13777, 'plPL', 'Co ty wyprawiasz? Omal mnie nie zdemaskowałeś, idioto! Mówiłem ci, żebyś schował kompas i mapy nawigacyjne w bezpiecznym miejscu – a nie zostawiał je na widoku, żeby każdy głupiec mógł je znaleźć.', '', 0),
(13778, 'plPL', 'Mistrz zadał sobie wiele trudu, by zdobyć informacje o położeniu Exodaru. Mogłeś zniweczyć całą operację, łącznie z przykrywką naszego szpiega w środku.', '', 0),
(13780, 'plPL', 'Spokojnie? Wiesz, co Kael\'thas robi z tymi, którzy go zawiodą, Geezle? Wieczne cierpienie i ból... NIE spartacz tego, głupcze.', '', 0),
(13781, 'plPL', 'Nasi zwiadowcy na Krwawej Mgle namierzyli naszego informatora. Ten głupiec Velen wkrótce odsłoni się i zostanie bez obrony – na tyle długo, byśmy zdążyli uderzyć! A teraz zejdź mi z oczu, zanim cię wyparuję...', '', 0),
(13785, 'plPL', '%s się śmieje.', '', 0),
(13787, 'plPL', 'Czy przeraża cię myśl, że są tacy, którzy służą Legionowi tak oddanie, że pozostają niezłomnymi obywatelami waszych żałosnych cywilizacji, dopóki nie zostaną wezwani?', '', 0),
(13791, 'plPL', 'Żyj w strachu, zgiń z woli Kael\'thasa... Wszystko jedno.', '', 0),
(13808, 'plPL', 'Chwała wspaniałemu bohaterowi!', '', 0),
(13809, 'plPL', 'Opowieść o twojej wyprawie będzie krążyć jeszcze przez długie lata!', '', 0),
(13810, 'plPL', 'Wreszcie mam o czym opowiadać wnukom... Wśród nas żył zdrajca królestwa!', '', 0),
(13811, 'plPL', 'Prawdę mówiąc, ten gnom nigdy mi się nie podobał...', '', 0),
(13812, 'plPL', 'Mamy szczęście, że przetrwaliśmy tę próbę. Gdyby nie ty, wszyscy na tej wyspie mogliby zginąć!', '', 0),
(13813, 'plPL', 'Ciekawe, ilu jeszcze takich żyje wśród nas. Iskrę znam od lat – nigdy by mi nie przyszło do głowy, że jest zdrajcą.', '', 0),
(13814, 'plPL', '', 'Chwała wspaniałemu bohaterowi!', 0),
(13815, 'plPL', '', 'Opowieść o twojej wyprawie będzie krążyć jeszcze przez długie lata!', 0),
(13816, 'plPL', '', 'Wreszcie mam o czym opowiadać wnukom... Wśród nas żył zdrajca królestwa!\n', 0),
(13817, 'plPL', '', 'Prawdę mówiąc, ten gnom nigdy mi się nie podobał...', 0),
(13818, 'plPL', '', 'Mamy szczęście, że przetrwaliśmy tę próbę. Gdyby nie ty, wszyscy na tej wyspie mogliby zginąć!', 0),
(13819, 'plPL', '', 'Ciekawe, ilu jeszcze takich żyje wśród nas. Iskrę znam od lat – nigdy by mi nie przyszło do głowy, że jest zdrajcą.', 0),
(13837, 'plPL', '[Furbolgijski] Dziękuję, $N!', '', 0),
(13977, 'plPL', '%s warczy na swoich porywaczy.', '', 0),
(13978, 'plPL', '[Furbolgijski] Furbolgi Cichej Sosny prędko nie zapomną twojej odwagi!', '', 0),
(13979, 'plPL', '[Furbolgijski] Ci, którzy zostali w Warowni Cichej Sosny, powitają cię jak bohatera!', '', 0),
(13980, 'plPL', '[Furbolgijski] Proroctwo jest prawdziwe!', '', 0),
(14007, 'plPL', 'Starając się pozyskać pomoc ludów tego świata przeciw Płonącemu Legionowi, musimy się też nauczyć żyć wśród nich w pokoju.$B$BPamiętaj o tym, gdy będziesz przemierzać Azeroth. Niech Światłość cię prowadzi.', '', 0),
(14038, 'plPL', 'Najeźdźcy Cichej Sosny, nadeszła pora, by uderzyć! Do ataku!', '', 0),
(14062, 'plPL', 'Gdzie znajdę więcej zakażonych chuchr nocnych tropicieli, Egzarcho?', 'Gdzie znajdę więcej zakażonych chuchr nocnych tropicieli, Egzarcho?', 0),
(14063, 'plPL', 'Zakażone chuchra nocnych tropicieli zdają się przychodzić z północy. Na twoim miejscu tam zacząłbym łowy.', '', 0),
(14076, 'plPL', 'Aha! Jest jedna!', '', 0),
(14077, 'plPL', 'Następna!', '', 0),
(14078, 'plPL', 'O, ale duża!', '', 0),
(14079, 'plPL', 'Ciekawe, czy w tych muszlach naprawdę słychać ocean.', '', 0),
(14080, 'plPL', 'To ironia losu: nie znoszę oceanu, ale uwielbiam plażę.', '', 0),
(14082, 'plPL', 'Tak, mistrzu, wszystko idzie zgodnie z planem.', '', 0),
(14083, 'plPL', '%s wkłada muszlę do plecaka.', '', 0),
(14084, 'plPL', '%s przykłada muszlę do ucha.', '', 0),
(14086, 'plPL', '%s ogląda muszlę.', '', 0),
(14090, 'plPL', 'A teraz cię potnę!', '', 0),
(14091, 'plPL', 'GIŃ!', '', 0),
(14092, 'plPL', 'Nie widzisz, że jestem zajęty?', '', 0),
(14093, 'plPL', 'To koniec, Iskro. Admirał wie, że to ty zdradziłeś Przymierze. Albo będziesz ze mną współpracować i powiesz mi wszystko, co wiesz, albo porozmawiamy na pięści.', 'To koniec, Iskro. Admirał wie, że to ty zdradziłeś Przymierze. Albo będziesz ze mną współpracować i powiesz mi wszystko, co wiesz, albo porozmawiamy na pięści.', 0),
(14123, 'plPL', '[Furbolgijski] Mil\'ork kix ilfin o oomtor...', '', 0),
(14124, 'plPL', '[Furbolgijski] Poorov\'tarkh!', '', 0),
(14125, 'plPL', '[Furbolgijski] Yar vartslaf?', '', 0),
(14126, 'plPL', '[Furbolgijski] Boro gomsho!', '', 0),
(14154, 'plPL', 'Czym mogę ci służyć, $gprzybyszu:przybyszko;?', '', 0),
(14155, 'plPL', 'Chcę obejrzeć twoje towary, Erghu.', 'Chcę obejrzeć twoje towary, Erghu.', 0),
(14156, 'plPL', 'Nazywam się Gurf, $gprzybyszu:przybyszko;. Gurf Dzielny!', '', 0),
(14157, 'plPL', 'Proszę, naucz mnie skórowania, Gurfie.', 'Proszę, naucz mnie skórowania, Gurfie.', 0),
(14158, 'plPL', 'Jestem Moordo, starszy łowca Cichej Sosny.', '', 0),
(14159, 'plPL', 'Chcę zostać garbarzem, Moordo. Proszę, naucz mnie.', 'Chcę zostać garbarzem, Moordo. Proszę, naucz mnie.', 0),
(14160, 'plPL', 'Witaj w moim sklepie!', '', 0),
(14161, 'plPL', 'Witaj, Parkacie. Chcę coś kupić.', 'Witaj, Parkacie. Chcę coś kupić.', 0),
(14162, 'plPL', 'Ach, $gprzybył Obiecany:przybyła Obiecana;. Witaj w Warowni Cichej Sosny.', '', 0),
(14163, 'plPL', 'Pomyślności, $N. Jestem Cicha Sosna Młodszy, dziedzic tronu Cichej Sosny.', '', 0),
(14164, 'plPL', 'To ty obronisz mój lud i zapoczątkujesz nową erę dobrobytu dla Cichej Sosny!', '', 0),
(14165, 'plPL', 'Zabić tyle zakażonych nocnych tropicieli, ile zdołam znaleźć... To będzie łatwizna.', 'Zabić tyle zakażonych nocnych tropicieli, ile zdołam znaleźć... To będzie łatwizna.', 0),
(14166, 'plPL', 'Dzięki za uleczenie, $N!', 'Dzięki za uleczenie, $N!', 0),
(14167, 'plPL', 'Pomocy! Chyba sam nie dam rady temu stworowi.', 'Pomocy! Chyba sam nie dam rady temu stworowi.', 0),
(14168, 'plPL', 'Czy ktoś mnie słyszy? Potrzebuję pomocy! Ten stwór mnie zabije!', 'Czy ktoś mnie słyszy? Potrzebuję pomocy! Ten stwór mnie zabije!', 0),
(14169, 'plPL', 'Nie mogę go dłużej powstrzymywać! Powiedzcie egzarsze, że dałem z siebie wszystko.', 'Nie mogę go dłużej powstrzymywać! Powiedzcie egzarsze, że dałem z siebie wszystko.', 0),
(14170, 'plPL', 'Jeszcze raz dzięki!', 'Jeszcze raz dzięki!', 0),
(14171, 'plPL', 'Kolejne zwycięstwo draenei!', 'Kolejne zwycięstwo draenei!', 0),
(14172, 'plPL', 'Kolejna zakażona bestia zniszczona!', 'Kolejna zakażona bestia zniszczona!', 0),
(14173, 'plPL', 'Jak mogłeś sądzić, że dorównasz czempionowi draenei!', 'Jak mogłeś sądzić, że dorównasz czempionowi draenei!', 0),
(14174, 'plPL', 'Ha! Ale łatwizna.', 'Ha! Ale łatwizna.', 0),
(14175, 'plPL', 'Mam polować na zakażone nocne tropiciele... To będzie łatwizna.', 'Mam polować na zakażone nocne tropiciele... To będzie łatwizna.', 0),
(14176, 'plPL', 'Gdzie, do Otchłani, podziały się te przeklęte smagacze?!', 'Gdzie, do Otchłani, podziały się te przeklęte smagacze?!', 0),
(14177, 'plPL', 'Hmm, lazurowe lwie paszcze? Skąd oni biorą te nazwy? Daedalowi chyba odbiło!', 'Hmm, lazurowe lwie paszcze? Skąd oni biorą te nazwy? Daedalowi chyba odbiło!', 0),
(14178, 'plPL', 'Te jelenie ani trochę nie przypominają talbuków.', 'Te jelenie ani trochę nie przypominają talbuków.', 0),
(14179, 'plPL', 'Ciekawe, co to za małe fioletowe stworzonko w wiosce... Z pewnością jest piękne.', 'Ciekawe, co to za małe fioletowe stworzonko w wiosce... Z pewnością jest piękne.', 0),
(14180, 'plPL', 'Pora spotkać się ze stwórcą, $N!', 'Pora spotkać się ze stwórcą, $N!', 0),
(14181, 'plPL', 'Pieniądze albo życie! A właściwie wystarczy samo życie...', 'Pieniądze albo życie! A właściwie wystarczy samo życie...', 0),
(14182, 'plPL', 'Twoja śmierć będzie godnym hołdem dla króla!', 'Twoja śmierć będzie godnym hołdem dla króla!', 0),
(14183, 'plPL', 'Za Srebrną Lunę! Za Słońcobieżcę!', 'Za Srebrną Lunę! Za Słońcobieżcę!', 0),
(14229, 'plPL', 'Kto śmie władać magią w mojej obecności?', 'Kto śmie władać magią w mojej obecności?', 0),
(14312, 'plPL', 'Dzięki za ostrzeżenie, $N! Przygotujemy się!', '', 0),
(14313, 'plPL', '$GObiecany:Obiecana;, dziękujemy ci za ostrzeżenie. Plemię Cichej Sosny będzie gotowe.', '', 0),
(14314, 'plPL', 'Dziękuję za ostrzeżenie, $N. Przygotujemy obronę.', '', 0),
(14381, 'plPL', '%s odwraca się do Tuluuna i uśmiecha się pogardliwie.', '%s odwraca się do Tuluuna i uśmiecha się pogardliwie.', 0),
(14382, 'plPL', 'Nie potrzebujemy tu takich jak ty.', 'Nie potrzebujemy tu takich jak ty.', 0),
(14383, 'plPL', 'Jak mam cokolwiek zrobić, gdy ten stwór szerzy swoją herezję?', 'Jak mam cokolwiek zrobić, gdy ten stwór szerzy swoją herezję?', 0),
(14384, 'plPL', '%s z niesmakiem wzdycha i wraca do pracy.', '%s z niesmakiem wzdycha i wraca do pracy.', 0),
(14592, 'plPL', 'Jako jedyny, jak się zdaje, ocalały spośród „Złamanych” mam obowiązek i zaszczyt kontynuować szamańskie nauki wieszcza Nobundo.', 'Jako jedyny, jak się zdaje, ocalały spośród „Złamanych” mam obowiązek i zaszczyt kontynuować szamańskie nauki wieszcza Nobundo.', 0),
(15941, 'plPL', 'Jak możesz dostać budyń, jeśli nie zjesz ryby?', '', 0),
(15942, 'plPL', 'Nie zjesz ryby, nie dostaniesz budyniu!', '', 0),
(17137, 'plPL', '%s się śmieje.', '', 0),
(17904, 'plPL', 'Myślę, że z pewną pomocą Taerix może być bliska przełomu.', '', 0),
(17908, 'plPL', '', 'Jestem pewna, że z naszą pomocą botaniczka Taerix znajdzie rozwiązanie naszych problemów.', 0),
(17909, 'plPL', 'Chcę kupić jedno z tych stworzeń.', 'Chcę kupić jedno z tych stworzeń.', 0),
(17912, 'plPL', 'Gdy środek neutralizujący miesza się z wodami jeziora, woda napromieniowana przez kryształ zdaje się oczyszczać.', '', 0),
(17925, 'plPL', 'Wygląda na to, że czas wypuścić cię z tej klatki.', '', 0),
(17934, 'plPL', 'Teraz nałożę na niego środek neutralizujący...', '', 0),
(17938, 'plPL', '', 'Tedonie, śmiało, wypróbuj środek neutralizujący na zmutowanym stworzeniu.', 0),
(17939, 'plPL', 'Udało się!', '', 0),
(18273, 'plPL', 'Jeśli Światłość nie może cię poprowadzić, przyjacielu, może ja zdołam ci pomóc. Czego potrzebujesz?', 'Jeśli Światłość nie może cię poprowadzić, przyjacielu, może ja zdołam ci pomóc. Czego potrzebujesz?', 0),
(18274, 'plPL', 'Ta wyspa potrafi być dziwna, prawda? Mogę coś dla ciebie zrobić?', 'Ta wyspa potrafi być dziwna, prawda? Mogę coś dla ciebie zrobić?', 0),
(18275, 'plPL', 'Szukasz przechowalni? W takim razie udaj się do bezpiecznego Exodaru... bankierzy chętnie ci pomogą.', 'Szukasz przechowalni? W takim razie udaj się do bezpiecznego Exodaru... bankierzy chętnie ci pomogą.', 0),
(18295, 'plPL', 'Hipogryfy mają dobrą opiekę przy samym Exodarze. Tam $gpowinieneś:powinnaś; się udać, jeśli chcesz polecieć do Krwawej Strażnicy.', 'Hipogryfy mają dobrą opiekę przy samym Exodarze. Tam $gpowinieneś:powinnaś; się udać, jeśli chcesz polecieć do Krwawej Strażnicy.', 0),
(18297, 'plPL', 'Funaam jest naszym urzędnikiem gildii. Jego biuro mieści się w Exodarze. Idź po prostu drogą, a trafisz tam w mig.', 'Funaam jest naszym urzędnikiem gildii. Jego biuro mieści się w Exodarze. Idź po prostu drogą, a trafisz tam w mig.', 0),
(18298, 'plPL', 'Nasza skromna gospoda znajduje się w północnej części Lazurowej Strażnicy; Chellan dobrze się tobą zajmie.', 'Nasza skromna gospoda znajduje się w północnej części Lazurowej Strażnicy; Chellan dobrze się tobą zajmie.', 0),
(18300, 'plPL', 'Esbina chętnie zaopiekuje się twoim zwierzęcym towarzyszem, przyjacielu. Czeka przed gospodą w Lazurowej Strażnicy.', 'Esbina chętnie zaopiekuje się twoim zwierzęcym towarzyszem, przyjacielu. Czeka przed gospodą w Lazurowej Strażnicy.', 0),
(18302, 'plPL', 'Ach, szukasz nauczyciela? W Lazurowej Strażnicy obozuje kilku mistrzów... czego szukasz?', 'Ach, szukasz nauczyciela? W Lazurowej Strażnicy obozuje kilku mistrzów... czego szukasz?', 0),
(18306, 'plPL', 'Druida? Nikt tutaj nie podąża tą ścieżką... ale słyszałem o kimś takim w pobliżu Exodaru. Chyba Shalannius?', 'Druida? Nikt tutaj nie podąża tą ścieżką... ale słyszałem o kimś takim w pobliżu Exodaru. Chyba Shalannius?', 0),
(18309, 'plPL', 'Acteon to nasz miejscowy tropiciel, i to dobry – noszone przez niego skóry świadczą o jego umiejętnościach. Jego obóz jest w południowo-wschodniej części Lazurowej Strażnicy.', 'Acteon to nasz miejscowy tropiciel, i to dobry – noszone przez niego skóry świadczą o jego umiejętnościach. Jego obóz jest w południowo-wschodniej części Lazurowej Strażnicy.', 0),
(18317, 'plPL', 'Jeśli chodzi o panowanie nad magią tajemną, nie musisz szukać dalej niż u Semida. Naucza we wschodniej części Lazurowej Strażnicy razem z Ruadą.', 'Jeśli chodzi o panowanie nad magią tajemną, nie musisz szukać dalej niż u Semida. Naucza we wschodniej części Lazurowej Strażnicy razem z Ruadą.', 0),
(18319, 'plPL', 'Zacna Tullas to szlachetna kobieta i niezłomna obrończyni Światłości. Swoich lekcji udziela w samej gospodzie.', 'Zacna Tullas to szlachetna kobieta i niezłomna obrończyni Światłości. Swoich lekcji udziela w samej gospodzie.', 0),
(18320, 'plPL', 'W niewielkiej, ale wygodnej gospodzie Chellan znajdziesz kapłana Guvana.', 'W niewielkiej, ale wygodnej gospodzie Chellan znajdziesz kapłana Guvana.', 0),
(18322, 'plPL', 'Należysz do szamanów? Hm. Chyba wolno ci wybrać własną ścieżkę... jakakolwiek by ona była. Tuluun ma mały, odosobniony obóz na północnym zachodzie Lazurowej Strażnicy.', 'Należysz do szamanów? Hm. Chyba wolno ci wybrać własną ścieżkę... jakakolwiek by ona była. Tuluun ma mały, odosobniony obóz na północnym zachodzie Lazurowej Strażnicy.', 0),
(18323, 'plPL', 'Ruada szkoli młodych wojowników we wschodniej części Lazurowej Strażnicy. Jeśli chcesz się szkolić w praktycznej sztuce wojennej, ona ci pomoże.', 'Ruada szkoli młodych wojowników we wschodniej części Lazurowej Strażnicy. Jeśli chcesz się szkolić w praktycznej sztuce wojennej, ona ci pomoże.', 0),
(18324, 'plPL', 'Po Lazurowej Mgle rozproszonych jest wielu wykwalifikowanych rzemieślników. Którego szukasz?', 'Po Lazurowej Mgle rozproszonych jest wielu wykwalifikowanych rzemieślników. Którego szukasz?', 0),
(18326, 'plPL', 'Daedal zna się na warzeniu mikstur. Pracuje ramię w ramię z Fateemą w zachodniej części Lazurowej Strażnicy.', 'Daedal zna się na warzeniu mikstur. Pracuje ramię w ramię z Fateemą w zachodniej części Lazurowej Strażnicy.', 0),
(18327, 'plPL', 'W Lazurowej Strażnicy nie mamy kuźni. Widziałem jednak kilku młodych kowali, którzy przychodzili z tego dziwnego obozowiska na południowym wybrzeżu. Może warto to sprawdzić.', 'W Lazurowej Strażnicy nie mamy kuźni. Widziałem jednak kilku młodych kowali, którzy przychodzili z tego dziwnego obozowiska na południowym wybrzeżu. Może warto to sprawdzić.', 0),
(18328, 'plPL', 'Nie mieliśmy wolnych kucharzy, ale to trochę dziwne... południowy wiatr niesie jakieś smakowite zapachy. Idź za nosem, co?', 'Nie mieliśmy wolnych kucharzy, ale to trochę dziwne... południowy wiatr niesie jakieś smakowite zapachy. Idź za nosem, co?', 0),
(18329, 'plPL', 'Nasi zaklinacze spędzają dnie w Exodarze, pracując nad najróżniejszymi projektami. Nahogg rozpocznie twoje szkolenie.', 'Nasi zaklinacze spędzają dnie w Exodarze, pracując nad najróżniejszymi projektami. Nahogg rozpocznie twoje szkolenie.', 0),
(18330, 'plPL', 'Tutejszy artefaktor, Daelo, nauczy cię podstaw inżynierii. Może pomożesz naszemu technikowi naprawić to niesprawne urządzenie łączności!', 'Tutejszy artefaktor, Daelo, nauczy cię podstaw inżynierii. Może pomożesz naszemu technikowi naprawić to niesprawne urządzenie łączności!', 0),
(18331, 'plPL', 'Fateema jest naszą anachoretką i okazała się nieoceniona w opiece nad ofiarami katastrofy. Swoje rzemiosło uprawia w zachodniej części Strażnicy.', 'Fateema jest naszą anachoretką i okazała się nieoceniona w opiece nad ofiarami katastrofy. Swoje rzemiosło uprawia w zachodniej części Strażnicy.', 0),
(18332, 'plPL', 'Aspirujący wędkarz... cóż, Diktynna mieszka na brzegu Brodu Ammen i dzięki sieci i wędce zaopatruje nas wszystkich. Jestem pewien, że przyda jej się pomoc.', 'Aspirujący wędkarz... cóż, Diktynna mieszka na brzegu Brodu Ammen i dzięki sieci i wędce zaopatruje nas wszystkich. Jestem pewien, że przyda jej się pomoc.', 0),
(18333, 'plPL', 'Heur bada miejscową roślinność od naszego lądowania. Będzie mógł cię poprowadzić. Znajdziesz go przy pracy z Daedalem na zachodnim skraju Lazurowej Strażnicy.', 'Heur bada miejscową roślinność od naszego lądowania. Będzie mógł cię poprowadzić. Znajdziesz go przy pracy z Daedalem na zachodnim skraju Lazurowej Strażnicy.', 0),
(18334, 'plPL', 'Nasi nowi sojusznicy, furbolgi Cichej Sosny, wyrazili chęć przejmowania skór, które znajdujemy. Mieszkają na północy; ja u nich szukałbym wiedzy.', 'Nasi nowi sojusznicy, furbolgi Cichej Sosny, wyrazili chęć przejmowania skór, które znajdujemy. Mieszkają na północy; ja u nich szukałbym wiedzy.', 0),
(18335, 'plPL', 'Dulvi to ta, której szukasz. Szkoli nowych poszukiwaczy w samym środku Strażnicy.', 'Dulvi to ta, której szukasz. Szkoli nowych poszukiwaczy w samym środku Strażnicy.', 0),
(18336, 'plPL', 'Udaj się do Warowni Cichej Sosny, przyjacielu. Tamtejsze furbolgi bardzo nam pomogły i może mają akurat taką wiedzę, jakiej potrzebujesz.', 'Udaj się do Warowni Cichej Sosny, przyjacielu. Tamtejsze furbolgi bardzo nam pomogły i może mają akurat taką wiedzę, jakiej potrzebujesz.', 0),
(18337, 'plPL', 'W Lazurowej Strażnicy nie mamy krawców. Spróbuj jednak w obozowisku na plaży – mają tam chyba sporo rzemieślników zza morza.', 'W Lazurowej Strażnicy nie mamy krawców. Spróbuj jednak w obozowisku na plaży – mają tam chyba sporo rzemieślników zza morza.', 0),
(18339, 'plPL', 'Szukasz szlifierza kamieni? Nasi jubilerzy są w Exodarze i czynią cuda z materiałami, które udało im się wydobyć. Gdy tam dotrzesz, porozmawiaj z Farii.', 'Szukasz szlifierza kamieni? Nasi jubilerzy są w Exodarze i czynią cuda z materiałami, które udało im się wydobyć. Gdy tam dotrzesz, porozmawiaj z Farii.', 0),
(18667, 'plPL', 'Czego chcesz? Mów śmiało. Nie powierzę ci żadnego z moich elekków, dopóki nie dowiedziesz swojego oddania i przyjaźni wobec naszego ludu.', 'Czego chcesz? Mów śmiało. Nie powierzę ci żadnego z moich elekków, dopóki nie dowiedziesz swojego oddania i przyjaźni wobec naszego ludu.', 0),
(19070, 'plPL', 'Ta ziemia wciąż nosi blizny przeszłości. Ciekawe, czy kiedykolwiek się zagoją.', '', 0),
(19071, 'plPL', 'Czy możesz rzucić zaklęcie, dzięki któremu będę $gmógł:mogła; oddychać i poruszać się pod wodą?', 'Czy możesz rzucić zaklęcie, dzięki któremu będę $gmógł:mogła; oddychać i poruszać się pod wodą?', 0),
